import re

BOLD_PATTERN = re.compile(r'\*\*(.+?)\*\*')
ITALIC_PATTERN = re.compile(r'_(.+?)_')


def escape_html(raw):
    out = raw.replace('&', '&amp;')
    out = out.replace('<', '&lt;')
    return out.replace('>', '&gt;')


def render_inline(raw):
    text = escape_html(raw)
    text = BOLD_PATTERN.sub(r'<strong>\1</strong>', text)
    return ITALIC_PATTERN.sub(r'<em>\1</em>', text)


def classify(line):
    stripped = line.strip()
    if not stripped:
        return 'blank', stripped
    if stripped.startswith('## '):
        return 'h2', stripped[3:].strip()
    if stripped.startswith('# '):
        return 'h1', stripped[2:].strip()
    if stripped.startswith('- '):
        return 'li', stripped[2:].strip()
    return 'text', stripped


def render_heading(kind, content):
    level = kind[1]
    return f'<h{level}>{render_inline(content)}</h{level}>'


def render_list(items):
    cells = [f'<li>{render_inline(item)}</li>' for item in items]
    joined = ''.join(cells)
    return f'<ul>{joined}</ul>'


def render_paragraph(lines):
    body = ' '.join(render_inline(line) for line in lines)
    return f'<p>{body}</p>'


def convert(text):
    if not isinstance(text, str):
        raise TypeError('convert() expects the document as a string')
    blocks = []
    paragraph = []
    items = []
    for line in text.splitlines():
        kind, content = classify(line)
        if kind != 'li' and items:
            blocks.append(render_list(items))
            items = []
        if kind != 'text' and paragraph:
            blocks.append(render_paragraph(paragraph))
            paragraph = []
        if kind == 'li':
            items.append(content)
        elif kind == 'text':
            paragraph.append(content)
        elif kind != 'blank':
            blocks.append(render_heading(kind, content))
    if items:
        blocks.append(render_list(items))
    if paragraph:
        blocks.append(render_paragraph(paragraph))
    return '\n'.join(blocks)


DOCUMENT = '\n'.join([
    '# Hello',
    '',
    '- World',
    '- A **bold** neighbour',
    '',
    '## Notes',
    'This paragraph is _emphasised_ in places',
    'and spans two source lines.',
])


def main():
    print(convert(DOCUMENT))


if __name__ == '__main__':
    main()

