def render_value(value):
    if isinstance(value, str):
        mark = '\''
        return mark + value + mark
    if value is None:
        return 'null'
    return str(value)


def render_columns(names):
    if not names:
        raise ValueError('at least one column name is required')
    return ', '.join(names)


def select_query(table, column_names):
    return f'select {render_columns(column_names)} from {table}'


def insert_query(table, column_names, values):
    if len(column_names) != len(values):
        raise ValueError('insert needs one value per column')
    rendered = ', '.join(render_value(value) for value in values)
    return f'insert into {table} ({render_columns(column_names)}) values ({rendered})'


def delete_query(table, column, value):
    return f'delete from {table} where {column} = {render_value(value)}'


def update_query(table, column, value, condition_column, condition_value):
    assignment = f'{column} = {render_value(value)}'
    condition = f'{condition_column} = {render_value(condition_value)}'
    return f'update {table} set {assignment} where {condition}'


BUILDERS = {
    'select': select_query,
    'insert': insert_query,
    'delete': delete_query,
    'update': update_query,
}


def build(arguments):
    queries = []
    for instruction in arguments:
        if not instruction:
            raise ValueError('an instruction must name an operation')
        operation = instruction[0]
        builder = BUILDERS.get(operation)
        if builder is None:
            raise ValueError(f'unsupported operation: {operation}')
        try:
            queries.append(builder(*instruction[1:]))
        except TypeError:
            raise ValueError(f'wrong number of arguments for {operation}')
    return queries


def main():
    table = 'users'
    key_column = 'id'
    role_column = 'role'
    user_columns = [
        key_column,
        'name',
    ]
    new_user = [
        7,
        'ada',
    ]
    new_role = 'admin'
    plan = [
        ('select', table, user_columns),
        ('insert', table, user_columns, new_user),
        ('update', table, role_column, new_role, key_column, 7),
        ('delete', table, key_column, 7),
    ]
    for query in build(plan):
        print(query)


if __name__ == '__main__':
    main()

