import re

DATE_PATTERN = re.compile(r'^\d{4}-\d{2}-\d{2}$')
TIME_PATTERN = re.compile(r'^\d{2}:\d{2}(:\d{2})?$')

NORMAL_TAG = 'normal'
CAUTION_TAG = 'caution'
FAILURE_TAG = 'failure'
FATAL_TAG = 'fatal'
UNKNOWN_TAG = 'unknown'

TAG_ORDER = [NORMAL_TAG, CAUTION_TAG, FAILURE_TAG, FATAL_TAG, UNKNOWN_TAG]


def tag_for(severity):
    if severity == 'info':
        return NORMAL_TAG
    if severity == 'warning':
        return CAUTION_TAG
    if severity == 'error':
        return FAILURE_TAG
    if severity == 'critical':
        return FATAL_TAG
    return UNKNOWN_TAG


def split_entry(entry):
    parts = entry.strip().split(maxsplit=3)
    if len(parts) < 4:
        return None
    date, time, severity, message = parts
    if not DATE_PATTERN.match(date):
        return None
    if not TIME_PATTERN.match(time):
        return None
    return severity.lower(), message


def format_entry(entry):
    fields = split_entry(entry)
    if fields is None:
        return '{}: {}'.format(UNKNOWN_TAG, entry.strip())
    severity, message = fields
    return '{}: {}'.format(tag_for(severity), message)


def analyze(logs):
    return [format_entry(entry) for entry in logs]


def count_by_tag(formatted):
    counts = {}
    for line in formatted:
        tag = line.split(':', 1)[0]
        counts[tag] = counts.get(tag, 0) + 1
    return counts


def report(formatted):
    counts = count_by_tag(formatted)
    pieces = []
    for tag in TAG_ORDER:
        if tag in counts:
            pieces.append('{}={}'.format(tag, counts[tag]))
    if not pieces:
        return 'no entries'
    return ', '.join(pieces)


def main():
    logs = [
        '2024-05-01 09:12:00 error disk full',
        '2024-05-01 09:13:10 info backup started',
        '2024-05-01 09:14:22 WARNING queue depth rising',
        '2024-05-01 09:15:47 critical database unreachable',
        '2024-05-01 09:16:03 debug cache flushed',
        'not a log line at all',
    ]
    formatted = analyze(logs)
    for line in formatted:
        print(line)
    print('summary: ' + report(formatted))


if __name__ == '__main__':
    main()

