OPERATORS = dict(
    add=' + ',
    subtract=' - ',
    multiply=' * ',
    divide=' / ',
    power=' ^ ',
)


def is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def format_operand(operand):
    if is_number(operand):
        return str(operand)
    if isinstance(operand, list):
        return format(operand)
    raise TypeError(f'operand is neither a number nor a subtree: {operand!r}')


def format(tree):
    if not isinstance(tree, list) or not tree:
        raise ValueError('a tree must be a non-empty list')
    operation = tree[0]
    if not isinstance(operation, str):
        raise ValueError('the first element must be an operation name')
    separator = OPERATORS.get(operation)
    if separator is None:
        raise ValueError(f'unsupported operation: {operation}')
    operands = tree[1:]
    if len(operands) < 2:
        raise ValueError(f'{operation} needs at least two operands')
    joined = separator.join(format_operand(operand) for operand in operands)
    return f'({joined})'


def operations(tree):
    found = [tree[0]]
    for operand in tree[1:]:
        if isinstance(operand, list):
            found.extend(operations(operand))
    return found


def depth(tree):
    levels = [depth(operand) for operand in tree[1:] if isinstance(operand, list)]
    return 1 + max(levels, default=0)


def report(label, tree):
    used = ', '.join(operations(tree))
    print(f'{label}: {format(tree)}')
    print(f'  operations: {used}')
    print(f'  nesting depth: {depth(tree)}')


def main():
    simple = ['add', 1, 2]
    inner = ['power', 3, 4]
    scaled = ['multiply', 2, inner]
    total = ['subtract', simple, scaled]
    ratio = ['divide', total, 5]
    report('simple sum', simple)
    report('mixed expression', total)
    report('final ratio', ratio)


if __name__ == '__main__':
    main()

