SPACE = ' '
PLUS = '+'


def scheme_for(protocol):
    if protocol == 'secure':
        return 'https'
    if protocol == 'web':
        return 'http'
    if protocol == 'file':
        return 'ftp'
    raise ValueError('unsupported protocol: {0}'.format(protocol))


def normalize_domain(domain):
    cleaned = str(domain).strip()
    if not cleaned:
        raise ValueError('the domain name must not be empty')
    return cleaned.strip('/')


def split_path(text):
    return [segment for segment in str(text).split('/') if segment]


def parse_query(text):
    params = []
    for chunk in str(text).split('&'):
        if not chunk:
            continue
        name, separator, value = chunk.partition('=')
        if not separator:
            raise ValueError('query parameter needs an equals sign: ' + chunk)
        params.append((name, value))
    return params


def encode_value(value):
    return str(value).replace(SPACE, PLUS)


def build_path(segments):
    parts = []
    for segment in segments:
        text = str(segment).strip('/')
        if text:
            parts.append('/' + text)
    return ''.join(parts)


def build_query(params):
    pairs = []
    for item in params:
        if len(item) != 2:
            raise ValueError('each query parameter needs a name and a value')
        name, value = item
        pairs.append(str(name) + '=' + encode_value(value))
    return '&'.join(pairs)


def construct(components):
    if len(components) != 4:
        raise ValueError('expected protocol, domain, path and query parts')
    protocol, domain, path, params = components
    address = scheme_for(protocol) + '://' + normalize_domain(domain)
    address += build_path(path)
    if params:
        address += '?' + build_query(params)
    return address


def report(components):
    return '{0:>7} | {1}'.format(components[0], construct(components))


def main():
    plain = [
        'web',
        'example.com',
        split_path('/search'),
        parse_query('query=hello'),
    ]
    secure = [
        'secure',
        'files.example.org',
        split_path('docs/reports'),
        parse_query('title=annual report&lang=en'),
    ]
    archive = [
        'file',
        'mirror.example.net',
        split_path('pub/linux/iso'),
        [],
    ]
    for site in (plain, secure, archive):
        print(report(site))


if __name__ == '__main__':
    main()

