HEX_DIGITS = '0123456789abcdef'


def _valid_hex(digits):
    for char in digits:
        if char not in HEX_DIGITS:
            return False
    return True


def named_to_hex(name):
    if name == 'black':
        return '#000000'
    if name == 'white':
        return '#ffffff'
    return None


def hex_to_rgb(code):
    digits = code[1:]
    red = int(digits[0:2], 16)
    green = int(digits[2:4], 16)
    blue = int(digits[4:6], 16)
    return 'rgb({0}, {1}, {2})'.format(red, green, blue)


def rgb_to_hex(text):
    inner = text[3:].strip()
    if not inner.startswith('('):
        return None
    if not inner.endswith(')'):
        return None
    parts = inner[1:-1].split(',')
    if len(parts) != 3:
        return None
    digits = ''
    for part in parts:
        value = part.strip()
        if not value.isdigit():
            return None
        number = int(value)
        if number > 255:
            return None
        digits += '{0:02x}'.format(number)
    return '#' + digits


def convert(color):
    text = color.strip()
    lowered = text.lower()
    named = named_to_hex(lowered)
    if named is not None:
        return named
    if lowered.startswith('#') and len(lowered) == 7 and _valid_hex(lowered[1:]):
        return hex_to_rgb(lowered)
    if lowered.startswith('rgb'):
        converted = rgb_to_hex(lowered)
        if converted is not None:
            return converted
    return 'invalid format'


def main():
    samples = [
        '#00ff00',
        'rgb(18, 52, 86)',
        'black',
        'white',
        'rgb(300, 0, 0)',
        '#12g456',
    ]
    for sample in samples:
        print('{0} -> {1}'.format(sample, convert(sample)))


if __name__ == '__main__':
    main()

