DIRECTIONS = (
    'north',
    'east',
    'south',
    'west',
)

STEPS = {
    'north': (0, 1),
    'east': (1, 0),
    'south': (0, -1),
    'west': (-1, 0),
}

TURNS = (
    'left',
    'right',
)

MOVES = (
    'forward',
    'backward',
)


def parse(commands):
    if not isinstance(commands, str):
        raise TypeError('commands must be given as a string')
    tokens = commands.split()
    for token in tokens:
        if token not in TURNS and token not in MOVES:
            raise ValueError('unknown command: ' + token)
    return tokens


def turn(facing, direction):
    index = DIRECTIONS.index(facing)
    if direction == 'left':
        index -= 1
    else:
        index += 1
    return DIRECTIONS[index % len(DIRECTIONS)]


def move(x, y, facing, command):
    dx, dy = STEPS[facing]
    if command == 'backward':
        dx, dy = -dx, -dy
    return x + dx, y + dy


def apply_command(state, command):
    x, y, facing = state
    if command in TURNS:
        return x, y, turn(facing, command)
    x, y = move(x, y, facing, command)
    return x, y, facing


def describe(state):
    x, y, facing = state
    return 'x is {0}, y is {1}, facing {2}'.format(x, y, facing)


def navigate(commands):
    state = (0, 0, 'north')
    for command in parse(commands):
        state = apply_command(state, command)
    return describe(state)


def report(route):
    label = route if route.strip() else '(no commands)'
    return label + ' -> ' + navigate(route)


def main():
    routes = [
        'forward right forward',
        'forward forward left backward',
        'right right forward',
    ]
    for route in routes:
        print(report(route))
    try:
        navigate('forward jump')
    except ValueError as error:
        print('error: {0}'.format(error))


if __name__ == '__main__':
