HAND_SIZE = 5
JOINER = 'of'
RANK_NAMES = 'two three four five six seven eight nine ten jack queen king ace'
SUIT_NAMES = 'hearts diamonds clubs spades'


def build_deck():
    cards = []
    for suit in SUIT_NAMES.split():
        for rank in RANK_NAMES.split():
            cards.append(' '.join([rank, JOINER, suit]))
    return cards


def sorted_deck(deck):
    return sorted(deck, key=lambda card: (len(card), card))


def suit_of(card):
    return card.rsplit(' ', 1)[-1]


def rank_of(card):
    return card.split(' ', 1)[0]


def suit_summary(hand):
    counts = {}
    for card in hand:
        suit = suit_of(card)
        counts[suit] = counts.get(suit, 0) + 1
    parts = [f'{suit} x{counts[suit]}' for suit in sorted(counts)]
    return ', '.join(parts)


def format_hand(number, hand):
    listing = ', '.join(hand)
    return f'Player {number} holds: {listing}'


def deal(players):
    if not isinstance(players, int):
        raise TypeError('the number of players must be an integer')
    if players < 1:
        raise ValueError('at least one player is required')
    deck = sorted_deck(build_deck())
    if players * HAND_SIZE > len(deck):
        raise ValueError('the deck cannot supply five cards to every player')
    hands = [[] for _ in range(players)]
    for _ in range(HAND_SIZE):
        for hand in hands:
            hand.append(deck.pop())
    return hands


def main():
    players = 2
    hands = deal(players)
    print(f'Dealing {HAND_SIZE} cards to each of {players} players')
    for number, hand in enumerate(hands, start=1):
        print(format_hand(number, hand))
        print(f'    suits: {suit_summary(hand)}')
        highest = max(hand, key=len)
        print(f'    longest card name is the {rank_of(highest)}')
    dealt = sum(len(hand) for hand in hands)
    print(f'{dealt} cards left the deck, {52 - dealt} remain undealt')


if __name__ == '__main__':
    main()

