GROUPABLE = frozenset({
    'word',
    'number',
    'whitespace',
})


def _kind(ch):
    if ch.isalpha():
        return 'word'
    if ch.isdigit():
        return 'number'
    if ch in ' \t\n':
        return 'whitespace'
    if ch in '.,!?':
        return 'punctuation'
    return 'symbol'


def tokenize(text):
    if not isinstance(text, str):
        raise TypeError('tokenize() requires a string input')
    tokens = []
    index = 0
    length = len(text)
    while index < length:
        kind = _kind(text[index])
        start = index
        index += 1
        if kind in GROUPABLE:
            while index < length and _kind(text[index]) == kind:
                index += 1
        tokens.append((text[start:index], kind))
    return tokens


def _whitespace_name(ch):
    if ch == ' ':
        return 'space'
    if ch == '\t':
        return 'tab'
    return 'newline'


def render(token, kind):
    if kind == 'whitespace':
        return '+'.join(_whitespace_name(ch) for ch in token)
    return token


def summarize(tokens):
    counts = {}
    for _token, kind in tokens:
        counts[kind] = counts.get(kind, 0) + 1
    return counts


def format_report(tokens):
    lines = []
    for token, kind in tokens:
        lines.append('{0:<12}{1}'.format(kind, render(token, kind)))
    counts = summarize(tokens)
    lines.append('-' * 24)
    for kind in sorted(counts):
        lines.append('{0:<12}{1}'.format(kind, counts[kind]))
    return '\n'.join(lines)


