DOC_EXTS = [
    '.txt',
    '.md',
    '.py',
]
IMG_EXTS = [
    '.png',
    '.jpg',
    '.gif',
]
ARCHIVE_EXTS = [
    '.zip',
    '.tar',
    '.gz',
]
TYPE_ORDER = [
    'folder',
    'document',
    'image',
    'archive',
]


def suffix_for(kind):
    if kind == 'folder':
        return '/'
    if kind == 'document':
        return ' doc'
    if kind == 'image':
        return ' img'
    if kind == 'archive':
        return ' zip'
    raise ValueError('unsupported item type: ' + repr(kind))


def prefix_for(depth):
    if depth == 0:
        return '*'
    segments = ['|   '] * (depth - 1)
    segments.append('| - ')
    return ''.join(segments)


def classify(token):
    if token.endswith('/'):
        return 'folder'
    dot = token.rfind('.')
    ext = token[dot:].lower() if dot > 0 else ''
    if ext in DOC_EXTS:
        return 'document'
    if ext in IMG_EXTS:
        return 'image'
    if ext in ARCHIVE_EXTS:
        return 'archive'
    raise ValueError('cannot classify entry: ' + repr(token))


def parse_outline(text):
    tree = []
    for raw in text.strip('\n').splitlines():
        stripped = raw.lstrip(' ')
        if not stripped:
            continue
        depth = (len(raw) - len(stripped)) // 4
        tree.append((depth, stripped.rstrip('/'), classify(stripped)))
    return tree


def format_tree(tree):
    lines = []
    for depth, name, kind in tree:
        if not isinstance(depth, int) or depth < 0:
            raise ValueError('invalid depth level: ' + repr(depth))
        if not name.strip():
            raise ValueError('item name must not be empty')
        lines.append(prefix_for(depth) + name + suffix_for(kind))
    return '\n'.join(lines)


format = format_tree


def summarize(tree):
    counts = {}
    for entry in tree:
        counts[entry[2]] = counts.get(entry[2], 0) + 1
    parts = [str(counts[kind]) + ' ' + kind for kind in TYPE_ORDER if kind in counts]
    if not parts:
        return 'empty tree'
    return ', '.join(parts)


OUTLINE = '''
project/
    README.md
    src/
        main.py
        assets/
            logo.png
    backups/
        release.zip
'''


def main():
    tree = parse_outline(OUTLINE)
    print(format_tree(tree))
    print(summarize(tree))


if __name__ == '__main__':
    main()

