import string

SPECIALS = '!@#$%^&*()-_=+[]{};:,.<>?/|~'
MIN_LENGTH = 8


def has_upper(password):
    return any(char in string.ascii_uppercase for char in password)


def has_lower(password):
    return any(char in string.ascii_lowercase for char in password)


def has_digit(password):
    return any(char in string.digits for char in password)


def has_symbol(password):
    return any(char in SPECIALS for char in password)


def validate(password):
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    feedback = []
    if len(password) < MIN_LENGTH:
        feedback.append('too short')
    if not has_upper(password):
        feedback.append('needs uppercase')
    if not has_lower(password):
        feedback.append('needs lowercase')
    if not has_digit(password):
        feedback.append('needs number')
    if not has_symbol(password):
        feedback.append('needs symbol')
    if not feedback:
        return 'strong'
    return ', '.join(feedback)


def score(password):
    checks = (has_upper, has_lower, has_digit, has_symbol)
    points = sum(1 for check in checks if check(password))
    if len(password) >= MIN_LENGTH:
        points += 1
    return points


def label(password):
    points = score(password)
    if points <= 2:
        return 'weak'
    if points < 5:
        return 'fair'
    return 'strong'


def report(password):
    verdict = validate(password)
    return '{0!r}: {1} [{2}]'.format(password, verdict, label(password))


def main():
    samples = 'pass Sup3r!Secret alllowercase Ab3$'.split()
    lines = [report(sample) for sample in samples]
    print('\n'.join(lines))
    strong = [sample for sample in samples if validate(sample) == 'strong']
    print('accepted: {0} of {1}'.format(len(strong), len(samples)))


if __name__ == '__main__':
    main()

