EMPTY_RANK = '8'
PAWN = 'p'
BACK_RANK = 'rnbqkbnr'
RANK_SEPARATOR = '/'
FIELD_SEPARATOR = ' '
CASTLING_AND_EN_PASSANT = '----'
HALFMOVE_CLOCK = '0'
FULLMOVE_NUMBER = '1'
FIELD_NAMES = 'placement color rights halfmove fullmove'.split()


def _validate_turn(turn):
    if not isinstance(turn, bool):
        raise TypeError('turn must be a boolean flag')
    return turn


def pawn_rank(white):
    rank = PAWN * 8
    return rank.upper() if white else rank


def back_rank(white):
    return BACK_RANK.upper() if white else BACK_RANK


def piece_placement():
    ranks = [back_rank(False), pawn_rank(False)]
    ranks.extend([EMPTY_RANK] * 4)
    ranks.append(pawn_rank(True))
    ranks.append(back_rank(True))
    return RANK_SEPARATOR.join(ranks)


def active_color(white):
    if white:
        return 'w'
    return 'b'


def color_name(code):
    if code == active_color(True):
        return 'White'
    return 'Black'


def initialize(turn):
    white_to_move = _validate_turn(turn)
    fields = [
        piece_placement(),
        active_color(white_to_move),
        CASTLING_AND_EN_PASSANT,
        HALFMOVE_CLOCK,
        FULLMOVE_NUMBER,
    ]
    return FIELD_SEPARATOR.join(fields)


def split_fields(fen):
    parts = fen.split(FIELD_SEPARATOR)
    if len(parts) != len(FIELD_NAMES):
        raise ValueError('a FEN string needs five space-separated fields')
    return dict(zip(FIELD_NAMES, parts))


def describe(fen):
    fields = split_fields(fen)
    placement = fields['placement']
    ranks = placement.split(RANK_SEPARATOR)
    pieces = sum(1 for char in placement if char.isalpha())
    mover = color_name(fields['color'])
    move_number = fields['fullmove']
    report = [f'Ranks described: {len(ranks)}']
    report.append(f'Pieces on board: {pieces}')
    report.append(f'{mover} to move on move {move_number}')
    return '\n'.join(report)


def main():
    opening = initialize(True)
    print(opening)
    print(describe(opening))
    print(initialize(False))


if __name__ == '__main__':
