import sys

NUMERALS = (
    (1000, 'M'),
    (900, 'CM'),
    (500, 'D'),
    (400, 'CD'),
    (100, 'C'),
    (90, 'XC'),
    (50, 'L'),
    (40, 'XL'),
    (10, 'X'),
    (9, 'IX'),
    (5, 'V'),
    (4, 'IV'),
    (1, 'I'),
)


def convert(number):
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError('convert expects a plain integer')
    if not 1 <= number <= 3999:
        raise ValueError(f'number out of range (1..3999): {number}')
    parts = []
    for value, symbol in NUMERALS:
        while number >= value:
            parts.append(symbol)
            number -= value
    return ''.join(parts)


def parse_number(text):
    cleaned = text.strip()
    if cleaned.startswith('+'):
        cleaned = cleaned[1:]
    if not cleaned:
        raise ValueError('no digits given')
    if not cleaned.isdigit():
        raise ValueError(f'not a whole number: {text.strip()}')
    return int(cleaned)


def format_row(number, numeral):
    return f'{number:>4}  {numeral}'


def main(argv):
    if not argv:
        print('usage: roman.py NUMBER [NUMBER ...]', file=sys.stderr)
        return 2
    written = 0
    failures = 0
    for argument in argv:
        try:
            number = parse_number(argument)
            numeral = convert(number)
        except (TypeError, ValueError) as error:
            print(f'skipped {argument!r}: {error}', file=sys.stderr)
            failures += 1
            continue
        written += len(numeral)
        print(format_row(number, numeral))
    summary = f'{written} characters produced'
    if failures:
        summary += f', {failures} input(s) rejected'
    print(summary)
    return 1 if failures else 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))

