LABEL_WIDTH = 10
BLANK_MARKER = 'blank'


def classify(line):
    if line.startswith('def '):
        return 'function'
    if line.startswith('class '):
        return 'object'
    if line.startswith('#'):
        return 'comment'
    if line.startswith('import '):
        return 'module'
    return 'code'


def is_blank(line):
    return line.strip() == ''


def decorate(line, number):
    label = classify(line).ljust(LABEL_WIDTH)
    digits = str(number).zfill(3)
    return label + digits + ':  |' + line


def format(code):
    if not isinstance(code, str):
        raise TypeError('code must be a single multi line string')
    numbered = []
    for number, line in enumerate(code.split('\n'), start=1):
        if is_blank(line):
            numbered.append(BLANK_MARKER)
        else:
            numbered.append(decorate(line, number))
    return '\n'.join(numbered)


def summarize(code):
    counts = {}
    for line in code.split('\n'):
        key = BLANK_MARKER if is_blank(line) else classify(line)
        counts[key] = counts.get(key, 0) + 1
    return counts


def report(counts):
    rows = []
    for key in sorted(counts):
        rows.append(key.ljust(LABEL_WIDTH) + str(counts[key]))
    return '\n'.join(rows)


def main():
    sample = '\n'.join([
        'import os',
        '',
        '# build the application object',
        'class App:',
        '    def run(self):',
        '        return os.getcwd()',
        '   ',
        'def main():',
        '    App().run()',
    ])
    print(format(sample))
    print(report(summarize(sample)))


if __name__ == '__main__':
    main()

