MONTHS = (
    'January',
    'February',
    'March',
    'April',
    'May',
    'June',
    'July',
    'August',
    'September',
    'October',
    'November',
    'December',
)

WEEKDAYS = (
    'Monday',
    'Tuesday',
    'Wednesday',
    'Thursday',
    'Friday',
    'Saturday',
    'Sunday',
)


def _split_fields(expression):
    if not isinstance(expression, str):
        raise TypeError('expression must be a string')
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError('expression must contain exactly five fields')
    return fields


def _month_name(number):
    if not 1 <= number <= len(MONTHS):
        raise ValueError('month must be a number from 1 to 12')
    return MONTHS[number - 1]


def _weekday_name(number):
    if not 1 <= number <= len(WEEKDAYS):
        raise ValueError('day of week must be a number from 1 to 7')
    return WEEKDAYS[number - 1]


def _field_label(field, unit, namer=None):
    if field == '*':
        return f'every {unit}'
    if not field.isdigit():
        raise ValueError(f'field {field!r} must be an asterisk or a number')
    number = int(field)
    if namer is None:
        return f'at {number} {unit}'
    return f'at {namer(number)} {unit}'


def describe(expression):
    minute, hour, day, month, weekday = _split_fields(expression)
    parts = [
        _field_label(minute, 'minute'),
        _field_label(hour, 'hour'),
        _field_label(day, 'day'),
        _field_label(month, 'month', _month_name),
        _field_label(weekday, 'weekday', _weekday_name),
    ]
    return ', '.join(parts)


def main():
    import sys

    expression = ' '.join(sys.argv[1:])
    if not expression:
        expression = '* 12 * 1 *'
    try:
        print(describe(expression))
    except (TypeError, ValueError) as error:
