        return arguments[index + 1]
    return ''


def validate_format(value):
    if value in VALID_FORMATS:
        return value
    return 'error'


def parse(arguments):
    verbose = False
    source = ''
    destination = ''
    fmt = ''
    files = []
    index = 0
    while index < len(arguments):
        token = arguments[index]
        if token == '--verbose':
            verbose = True
        elif token == '--quiet':
