        elif token == '--output':
            destination = take_value(arguments, index)
            index += 1
        elif token == '--input':
            source = take_value(arguments, index)
            index += 1
        elif token == '--format':
            fmt = validate_format(take_value(arguments, index))
            index += 1
        elif not token.startswith('-'):
            files.append(token)
        index += 1
    return (verbose, source, destination, fmt, files)


