from collections import OrderedDict

PIXEL_PROPERTIES = frozenset('width height margin'.split())
COMMENT_MARKER = '#'
FIELD_SEPARATOR = '|'


def _validate(index, entry):
    if not isinstance(entry, (tuple, list)):
        raise TypeError(f'rule {index} must be a tuple or a list')
    if len(entry) != 3:
        raise ValueError(f'rule {index} needs a selector, a property and a value')
    selector, prop, value = (str(part).strip() for part in entry)
    if not selector:
        raise ValueError(f'rule {index} has an empty selector')
    if not prop:
        raise ValueError(f'rule {index} has an empty property name')
    return selector, prop, value


def _format_value(prop, value):
    if prop in PIXEL_PROPERTIES and value.isdigit():
        value = f'{value}px'
    if 'link' in value:
        value = f'url({value})'
    return value


def _group(styles):
    grouped = OrderedDict()
    for index, entry in enumerate(styles, start=1):
        selector, prop, value = _validate(index, entry)
        grouped.setdefault(selector, []).append((prop, _format_value(prop, value)))
    return grouped


def _render_block(selector, declarations):
    parts = [f'{selector} {{']
    for prop, value in declarations:
        parts.append(f'{prop}: {value};')
    parts.append('}')
    return ' '.join(parts)


def generate(styles):
    grouped = _group(styles)
    blocks = [_render_block(selector, declarations) for selector, declarations in grouped.items()]
    return '\n\n'.join(blocks)


def parse_rules(text):
    rules = []
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith(COMMENT_MARKER):
            continue
        rules.append(tuple(part.strip() for part in line.split(FIELD_SEPARATOR)))
    return rules


def main():
    source = '''
    # page frame
    body | color | black
    body | margin | 12
    body | background | banner-link.png
    h1 | width | 640
    h1 | font-family | serif
    '''
    print(generate(parse_rules(source)))


if __name__ == '__main__':
    main()

