WIDTH = 21
WEEK_LENGTH = 7
RULE = '-' * WIDTH
DAY_NAMES = 'Mo Tu We Th Fr Sa Su'
WINTER_MONTHS = 'January February December'
SPRING_MONTHS = 'March April May'
SUMMER_MONTHS = 'June July August'
AUTUMN_MONTHS = 'September October November'

import sys


def season_of(month):
    'Return the season name that the given month belongs to.'
    name = month.strip().title()
    if name in WINTER_MONTHS.split():
        return 'winter'
    if name in SPRING_MONTHS.split():
        return 'spring'
    if name in SUMMER_MONTHS.split():
        return 'summer'
    if name in AUTUMN_MONTHS.split():
        return 'autumn'
    raise ValueError(f'unknown month name: {month}')


def validate(days, start, month):
    'Check the calendar arguments and return the matching season.'
    if isinstance(days, bool) or not isinstance(days, int):
        raise TypeError('days must be an integer')
    if not 28 <= days <= 31:
        raise ValueError('days must be between 28 and 31')
    if start not in range(WEEK_LENGTH):
        raise ValueError('start must be an integer from 0 to 6')
    if not month.strip():
        raise ValueError('month name must not be empty')
    return season_of(month)


def build_weeks(days, start):
    'Build one string per calendar week, padding the leading empty days.'
    weeks = []
    week = ' ' * (3 * start)
    filled = start
    for day in range(1, days + 1):
        week += f'{day:2d} '
        filled += 1
        if filled == WEEK_LENGTH:
            weeks.append(week)
            week = ''
            filled = 0
    if week:
        weeks.append(week)
    return weeks


def format(days, start, month):
    'Return the full text calendar grid for a single month.'
    season = validate(days, start, month)
    lines = [RULE, DAY_NAMES, RULE]
    lines.extend(build_weeks(days, start))
    lines.append(f'{RULE} {season}')
    return '\n'.join(lines)


def main():
    args = sys.argv[1:]
    if len(args) == 3:
        print(format(int(args[0]), int(args[1]), args[2]))
    else:
        print(format(30, 0, 'November'))


if __name__ == '__main__':
    main()

