def _is_ignored(line):
    if not line:
        return True
    if line.startswith(';'):
        return True
    return line.startswith('#')


def _is_header(line):
    if not line.startswith('['):
        return False
    return line.endswith(']')


def _coerce(value):
    lowered = value.lower()
    if lowered == 'true':
        return True
    if lowered == 'false':
        return False
    if lowered == 'none':
        return None
    if value.startswith('~') and len(value) > 1:
        if value.endswith('~'):
            return value[1:-1]
    return value


def parse(content):
    entries = []
    section = ''
    for raw in content.splitlines():
        line = raw.strip()
        if _is_ignored(line):
            continue
        if _is_header(line):
            section = line[1:-1].strip()
            continue
        if '=' in line:
            name, _, value = line.partition('=')
            name = name.strip()
            if not name:
                raise ValueError(f'missing property name in line: {raw!r}')
            entries.append((section, name, _coerce(value.strip())))
    return entries


def format_value(value):
    if value is None:
        return 'none'
    if value is True:
        return 'true'
    if value is False:
        return 'false'
    return str(value)


def render(entries):
    lines = []
    for section, name, value in entries:
        label = section or '(global)'
        lines.append(f'{label}: {name} = {format_value(value)}')
    return '\n'.join(lines)


def section_names(entries):
    seen = []
    for section, _name, _value in entries:
        label = section or '(global)'
        if label not in seen:
            seen.append(label)
    return seen


