import sys

LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
CODES = '.- -... -.-. -.. . ..-. --. .... .. .--- -.- .-.. -- -. --- .--. --.- .-. ... - ..- ...- .-- -..- -.-- --..'
MORSE = dict(zip(LETTERS, CODES.split()))
WORD_SEPARATOR = '/'
SYMBOLS = './-'
SYMBOL_NAMES = 'dot slash dash'.split()
NAMES = dict(zip(SYMBOLS, SYMBOL_NAMES))
DIVIDER = '\n--------------------------------\n'


def translate(message):
    'Turn letters and spaces into a telegraph signal of dots, dashes and slashes.'
    if not isinstance(message, str):
        raise TypeError('message must be a string')
    signals = []
    for char in message:
        upper = char.upper()
        if upper == ' ':
            signals.append(WORD_SEPARATOR)
        elif upper in MORSE:
            signals.append(MORSE[upper])
    return ' '.join(signals)


def spell(signal):
    'Read a signal out loud, naming every symbol and every gap.'
    spoken = []
    for char in signal:
        if char == ' ':
            spoken.append('space')
        else:
            spoken.append(NAMES[char])
    return ' '.join(spoken)


def report(message):
    'Build a three line summary of one translated message.'
    signal = translate(message)
    lines = ['message: ' + message]
    lines.append('signal:  ' + signal)
    lines.append('spoken:  ' + spell(signal))
    return '\n'.join(lines)


SAMPLES = 'SOS|Hello World|to be, or not to be'


def main(argv):
    if len(argv) > 1:
        messages = [' '.join(argv[1:])]
    else:
        messages = SAMPLES.split('|')
    blocks = [report(message) for message in messages]
    print(DIVIDER.join(blocks))


if __name__ == '__main__':
    main(sys.argv)

