SEPARATOR = ', '
PREFIX = 'today is'


def classify_temperature(temperature):
    if temperature > 30:
        return 'hot'
    if temperature < 10:
        return 'cold'
    return 'mild'


def classify_humidity(humidity):
    if humidity > 80:
        return 'humid'
    if humidity < 40:
        return 'dry'
    return 'normal'


def classify_wind(wind_speed):
    if wind_speed > 20:
        return 'windy'
    return 'calm'


def validate_reading(reading):
    if len(reading) != 3:
        raise ValueError('each reading needs temperature, humidity and wind speed')
    for value in reading:
        if not isinstance(value, (int, float)):
            raise TypeError('readings must contain numbers only')
    humidity = reading[1]
    if not 0 <= humidity <= 100:
        raise ValueError('humidity must be a percentage between 0 and 100')
    if reading[2] < 0:
        raise ValueError('wind speed cannot be negative')
    return tuple(reading)


def describe_weather(readings):
    sentences = []
    for reading in readings:
        temperature, humidity, wind_speed = validate_reading(reading)
        parts = [
            classify_temperature(temperature),
            classify_humidity(humidity),
            classify_wind(wind_speed),
        ]
        sentences.append(f'{PREFIX} {SEPARATOR.join(parts)}')
    return sentences


def format_report(readings):
    lines = []
    sentences = describe_weather(readings)
    for reading, sentence in zip(readings, sentences):
        measurements = f'{reading[0]}C / {reading[1]}% / {reading[2]}km/h'
        lines.append(f'{measurements:<22}-> {sentence}')
    return '\n'.join(lines)


