_SOUND_TABLE = (
    'dog woof',
    'cat meow',
    'cow moo',
    'pig oink',
    'duck quack',
)

DEFAULT_SOUND = 'silence'


def _build_sounds(table):
    sounds = {}
    for entry in table:
        name, sound = entry.split()
        sounds[name] = sound
    return sounds


SOUNDS = _build_sounds(_SOUND_TABLE)


def normalize(animal):
    if not isinstance(animal, str):
        raise TypeError('animal names must be strings')
    cleaned = animal.strip().lower()
    if not cleaned:
        raise ValueError('animal names must not be blank')
    return cleaned


def sound_for(animal):
    return SOUNDS.get(normalize(animal), DEFAULT_SOUND)


def verse(animal):
    name = normalize(animal)
    return '{0} says {1} {1}'.format(name, sound_for(name))


def animal_song(animals):
    if isinstance(animals, str):
        raise TypeError('expected a list of animal names, not one string')
    return [verse(animal) for animal in animals]


def unknown_animals(animals):
    strays = []
    for animal in animals:
        name = normalize(animal)
        if name not in SOUNDS:
            strays.append(name)
    return strays


def format_song(animals):
    lines = []
    for index, line in enumerate(animal_song(animals), start=1):
        lines.append('{0:>2}. {1}'.format(index, line))
    strays = unknown_animals(animals)
    if strays:
        joined = ', '.join(strays)
        lines.append('unknown: {0}'.format(joined))
    return '\n'.join(lines)


def main():
    farm = [
        'dog',
        'Cat',
        ' cow ',
        'pig',
        'duck',
        'yeti',
    ]
    print(format_song(farm))
    print('verses sung: {0}'.format(len(animal_song(farm))))
    print(verse('duck'))


if __name__ == '__main__':
    main()

