NUCLEOTIDES = frozenset('AUGC')
STOP = 'stop'
UNKNOWN = 'unknown'
CODON_LENGTH = 3

CODON_TABLE = dict(
    AUG='methionine',
    UAA=STOP,
    UUU='phenylalanine',
    UUC='phenylalanine',
    UUA='leucine',
    UUG='leucine',
    UCU='serine',
    UCC='serine',
)


def clean_rna(rna):
    if not isinstance(rna, str):
        raise TypeError('rna must be given as a string')
    compact = ''.join(rna.split()).upper()
    for base in compact:
        if base not in NUCLEOTIDES:
            raise ValueError(f'invalid nucleotide {base!r} in strand')
    return compact


def chunk_codons(rna):
    if len(rna) % CODON_LENGTH:
        raise ValueError('strand length must be a multiple of three')
    return [rna[i:i + CODON_LENGTH] for i in range(0, len(rna), CODON_LENGTH)]


def translate(rna):
    amino_acids = []
    for codon in chunk_codons(clean_rna(rna)):
        amino_acid = CODON_TABLE.get(codon, UNKNOWN)
        if amino_acid == STOP:
            return amino_acids
        amino_acids.append(amino_acid)
    return amino_acids


def format_protein(rna):
    try:
        amino_acids = translate(rna)
    except ValueError as err:
        return f'{rna} rejected: {err}'
    if amino_acids:
        joined = ', '.join(amino_acids)
    else:
        joined = '(no amino acids)'
    return f'{rna} -> {joined}'


def main():
    strands = [
        'AUGUUUUAA',
        'UUCUUGUCC',
        'AUG UCU UAA UUU',
        'UAAAUG',
        'AUGCCCUUA',
        'AUGUU',
        'AUGXYZ',
    ]
    for strand in strands:
        print(format_protein(strand))


if __name__ == '__main__':
    main()

