MESSAGES = {
    404: 'not found',
    500: 'server error',
    403: 'forbidden',
    401: 'unauthorized',
    400: 'bad request',
}

FALLBACK = 'unknown error'
PREFIX = 'error: '
SEPARATOR = ','


def describe_code(code):
    if isinstance(code, bool) or not isinstance(code, int):
        raise TypeError('error codes must be integers')
    return PREFIX + MESSAGES.get(code, FALLBACK)


def diagnose(codes):
    if isinstance(codes, (str, bytes)):
        raise TypeError('expected a list of integer error codes')
    return [describe_code(code) for code in codes]


def parse_codes(text):
    codes = []
    for token in text.split(SEPARATOR):
        for word in token.split():
            if not word.lstrip('-').isdigit():
                raise ValueError('not a valid error code: ' + word)
            codes.append(int(word))
    return codes


def is_recognised(code):
    return code in MESSAGES


def summarise(codes):
    known = sum(1 for code in codes if is_recognised(code))
    unknown = len(codes) - known
    parts = ['{0} recognised'.format(known)]
    if unknown:
        parts.append('{0} unrecognised'.format(unknown))
    return ', '.join(parts)


def report(text):
    codes = parse_codes(text)
    lines = []
    for code, message in zip(codes, diagnose(codes)):
        lines.append('{0:>5}  {1}'.format(code, message))
    lines.append('-' * 30)
    lines.append(summarise(codes))
    return '\n'.join(lines)


def main():
    samples = ['404, 500']
    samples.append('400 401 403 404 500 418')
    for sample in samples:
        print('input: ' + sample)
        print(report(sample))
        print()
    try:
        report('404 oops')
    except ValueError as exc:
        print('rejected: {0}'.format(exc))


if __name__ == '__main__':
    main()

