'''Format vehicle registration lines from raw record tuples.'''


def prefix_for(kind):
    '''Return the registration prefix used for a vehicle type.'''
    if kind == 'car':
        return 'passenger vehicle'
    if kind == 'truck':
        return 'commercial cargo'
    if kind == 'motorcycle':
        return 'two wheeler'
    if kind == 'bus':
        return 'passenger transport'
    raise ValueError(f'unsupported vehicle type: {kind!r}')


def normalize_record(record):
    '''Validate one record and return (prefix, color, year, make, model).'''
    if len(record) != 5:
        raise ValueError('a record must hold type, make, model, year and color')
    kind, make, model, year, color = record
    prefix = prefix_for(str(kind).strip().lower())
    try:
        year = int(year)
    except (TypeError, ValueError):
        raise ValueError('the year field must be a whole number') from None
    if not 1885 <= year <= 2100:
        raise ValueError(f'the year {year} is outside the supported range')
    cleaned = []
    for field in (color, make, model):
        text = str(field).strip()
        if not text:
            raise ValueError('make, model and color must not be empty')
        cleaned.append(text)
    return (prefix, cleaned[0], year, cleaned[1], cleaned[2])


def format_registration(record):
    '''Build the registration string for a single vehicle record.'''
    prefix, color, year, make, model = normalize_record(record)
    return f'{prefix}: {color} {year} {make} {model}'


def register_vehicles(records):
    '''Return formatted registration strings for every record given.'''
    return [format_registration(record) for record in records]


def parse_record(line):
    '''Turn a comma separated fleet line into a vehicle record tuple.'''
    fields = [part.strip() for part in line.split(',')]
    if len(fields) != 5:
        raise ValueError(f'expected five fields, got {len(fields)}')
    return tuple(fields)


def count_by_prefix(registrations):
    '''Count how many registrations share each prefix.'''
    tally = {}
    for line in registrations:
        prefix = line.split(':')[0]
        tally[prefix] = tally.get(prefix, 0) + 1
    return tally


def main():
    source = [
        'car, ford, focus, 2015, blue',
        'truck, volvo, fh16, 2019, white',
        'motorcycle, honda, cb500f, 2021, red',
        'bus, mercedes, citaro, 2008, green',
        'tractor, deere, 6120m, 2017, yellow',
    ]
    accepted = []
    for line in source:
        try:
            accepted.append(parse_record(line))
        except ValueError as error:
            print(f'unreadable line: {error}')
    registrations = []
    for record in accepted:
        try:
            registrations.extend(register_vehicles([record]))
        except ValueError as error:
            print(f'rejected record: {error}')
    for line in registrations:
        print(line)
    for prefix, count in sorted(count_by_prefix(registrations).items()):
        print(f'{prefix} -> {count}')


if __name__ == '__main__':
    main()

