MIN_LENGTH = 8
FORBIDDEN_WORD = 'password'
VALID_MESSAGE = 'valid'
COLUMN_SEPARATOR = '  |  '


def validate_password(password):
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    messages = []
    if len(password) < MIN_LENGTH:
        messages.append('too short')
    if not any(character.isdigit() for character in password):
        messages.append('missing number')
    if not any(character.isupper() for character in password):
        messages.append('missing uppercase')
    if not any(character.islower() for character in password):
        messages.append('missing lowercase')
    if ' ' in password:
        messages.append('contains space')
    if FORBIDDEN_WORD in password:
        messages.append('contains forbidden word')
    if not messages:
        return [VALID_MESSAGE]
    return messages


def validate_passwords(passwords):
    if not isinstance(passwords, (list, tuple)):
        raise TypeError('passwords must be a list of strings')
    return [validate_password(password) for password in passwords]


def format_report(passwords, results):
    width = max([len(password) for password in passwords] + [len(FORBIDDEN_WORD)])
    header_label = 'password'
    lines = [header_label.ljust(width) + COLUMN_SEPARATOR + 'messages']
    lines.append('-' * (width + len(COLUMN_SEPARATOR) + len(header_label)))
    for password, messages in zip(passwords, results):
        joined = ', '.join(messages)
        lines.append(password.ljust(width) + COLUMN_SEPARATOR + joined)
    return '\n'.join(lines)


def summarize(results):
    total = len(results)
    accepted = sum(1 for messages in results if messages == [VALID_MESSAGE])
    template = 'checked {0} password(s): {1} accepted, {2} rejected'
    return template.format(total, accepted, total - accepted)


def main():
    passwords = [
        'pass',
        'Passw0rd',
        'hunter2',
        'My Secret 1A',
        'Correct1Horse',
    ]
    results = validate_passwords(passwords)
    print(format_report(passwords, results))
    print(summarize(results))


if __name__ == '__main__':
    main()

