UNIT_SPEC = (
    'g grams',
    'kg kilograms',
    'ml milliliters',
    'l liters',
    'tbsp tablespoons',
    'tsp teaspoons',
)
NO_UNIT = 'none'
UNIT_WORDS = dict(entry.split() for entry in UNIT_SPEC)


def expand_unit(unit):
    key = str(unit).strip().lower()
    if key == NO_UNIT:
        return None
    if key not in UNIT_WORDS:
        raise ValueError(f'unknown unit: {unit!r}')
    return UNIT_WORDS[key]


def format_amount(amount):
    if isinstance(amount, bool) or not isinstance(amount, (int, float)):
        raise ValueError(f'amount must be a number, got {amount!r}')
    if isinstance(amount, float):
        return f'{amount:g}'
    return str(amount)


def format_ingredient(amount, unit, item):
    name = str(item).strip()
    if not name:
        raise ValueError('item name must not be empty')
    quantity = format_amount(amount)
    word = expand_unit(unit)
    if word is None:
        return f'{quantity} {name}'
    return f'{quantity} {word} of {name}'


def format_ingredients(ingredients):
    lines = []
    for position, entry in enumerate(ingredients, start=1):
        if len(entry) != 3:
            raise ValueError(f'ingredient {position} needs an amount, a unit and a name')
        amount, unit, item = entry
        lines.append(format_ingredient(amount, unit, item))
    return lines


def parse_amount(text):
    try:
        return float(text) if '.' in text else int(text)
    except ValueError:
        raise ValueError(f'bad amount: {text!r}')


def parse_entry(text):
    parts = text.split(None, 2)
    if len(parts) != 3:
        raise ValueError(f'cannot read amount, unit and name from {text!r}')
    return parse_amount(parts[0]), parts[1], parts[2]


def render_recipe(title, ingredients):
    lines = format_ingredients(ingredients)
    report = [title.upper()]
    report.extend(f'- {line}' for line in lines)
    report.append(f'total items: {len(lines)}')
    return '\n'.join(report)


def main():
    raw = [
        '100 g sugar',
        '1 none egg',
        '250 ml milk',
        '0.5 kg flour',
        '2 tbsp butter',
        '1.5 tsp vanilla extract',
        '1 l water',
    ]
    print(render_recipe('pancake batter', [parse_entry(line) for line in raw]))
    try:
        format_ingredients([parse_entry('3 cups rice')])
    except ValueError as error:
        print(f'skipped: {error}')


if __name__ == '__main__':
    main()

