import sys

INVALID_LABEL = 'invalid'
DEFAULT_CATEGORY = 'other'
HEADER = (
    'username',
    'domain',
    'category',
)


def domain_suffix(domain):
    if '.' not in domain:
        return ''
    return domain.rsplit('.', 1)[1].lower()


def categorize(domain):
    suffix = domain_suffix(domain)
    if suffix == 'com':
        return 'commercial'
    if suffix == 'org':
        return 'nonprofit'
    if suffix == 'edu':
        return 'educational'
    if suffix == 'gov':
        return 'government'
    if suffix == 'net':
        return 'network'
    return DEFAULT_CATEGORY


def parse_email(email):
    text = email.strip()
    if text.count('@') != 1:
        return (INVALID_LABEL,) * 3
    username, domain = text.split('@')
    if not username or not domain:
        return (INVALID_LABEL,) * 3
    return (username, domain, categorize(domain))


def categorize_emails(emails):
    return [parse_email(email) for email in emails]


def format_row(entry):
    username, domain, category = entry
    return f'{username:<20}{domain:<24}{category}'


def summarize(entries):
    counts = {}
    for entry in entries:
        counts[entry[2]] = counts.get(entry[2], 0) + 1
    return [f'{name:<20}{counts[name]}' for name in sorted(counts)]


def build_report(entries):
    lines = [format_row(HEADER), '-' * 56]
    lines.extend(format_row(entry) for entry in entries)
    lines.append('')
    lines.append('category totals')
    lines.extend(summarize(entries))
    return '\n'.join(lines)


def main():
    raw = sys.argv[1:] or sys.stdin.read().split()
    if not raw:
        print('usage: categorize.py EMAIL [EMAIL ...]', file=sys.stderr)
        return 1
    print(build_report(categorize_emails(raw)))
    return 0


if __name__ == '__main__':
    sys.exit(main())

