    'latte',
    'cappuccino',
    'espresso',
    'americano',
)

MILKS = (
    'whole',
    'skim',
    'oat',
    'almond',
    'none',
)

SYRUPS = (
    'vanilla',
    'caramel',
    'none',
)


def _checked(value, allowed, label):
    cleaned = str(value).strip().lower()
    if cleaned not in allowed:
        raise ValueError(f'invalid {label}: {value!r}')
    return cleaned


def parse_order(text):
    fields = text.split()
    if len(fields) != 4:
        raise ValueError(f'expected size, type, milk and syrup in {text!r}')
    return tuple(fields)


def format_order(order):
    size, drink, milk, syrup = order
    parts = [_checked(size, SIZES, 'size')]
    parts.append(_checked(drink, DRINKS, 'drink type'))
    milk = _checked(milk, MILKS, 'milk choice')
    syrup = _checked(syrup, SYRUPS, 'syrup choice')
    if milk != 'none':
        parts.append('with')
        parts.append(milk)
        parts.append('milk')
    if syrup != 'none':
        parts.append('and')
        parts.append(syrup)
        parts.append('syrup')
    return ' '.join(parts)


def build_orders(orders):
    return [format_order(order) for order in orders]


