    if not descriptions:
        return 'No orders to prepare.'
    lines = [f'Preparing {len(descriptions)} order(s):']
    for number, description in enumerate(descriptions, start=1):
        lines.append(f'  {number}. {description}')
    return '\n'.join(lines)


