def parse_items(spec):
    if not isinstance(spec, str):
        raise TypeError('spec must be a string of comma separated items')
    parts = spec.split(',')
    return [part.strip() for part in parts]


def build_menu(items):
    if isinstance(items, str):
        raise TypeError('items must be a list, not a single string')
    lines = ['main menu']
    lines.append('=' * 10)
    for index, item in enumerate(items, start=1):
        label = item.strip()
        if not label:
            lines.append('empty item skipped')
            continue
        lines.append(f'{index}) {label.upper()}')
    lines.append('-' * 10)
    lines.append('9) BACK')
    lines.append('0) EXIT')
    return lines


def render_menu(lines):
    return '\n'.join(lines)


def resolve_choice(choice, items):
    key = choice.strip()
    if key == '9':
        return 'back'
    if key == '0':
        return 'exit'
    if not key.isdigit():
        return 'invalid choice'
    position = int(key)
    if position < 1 or position > len(items):
        return 'no such entry'
    selected = items[position - 1].strip()
    if not selected:
        return 'entry unavailable'
    return f'run {selected.lower()}'


def describe_menu(items):
    usable = [item for item in items if item.strip()]
    skipped = len(items) - len(usable)
    summary = f'{len(usable)} entries available'
    if skipped:
        summary += f', {skipped} skipped'
    return summary


def main():
    spec = 'start, ,save file,quit'
    items = parse_items(spec)
    menu = build_menu(items)
    print(render_menu(menu))
    print(describe_menu(items))
    inputs = parse_items('1,2,4,7,x,9,0')
    for choice in inputs:
        print(f'input {choice} -> {resolve_choice(choice, items)}')


if __name__ == '__main__':
    main()

