text_nat:
GREEN_DURATION = 30
YELLOW_DURATION = 5
RED_DURATION = 20
WALK_WINDOW = 5
CYCLE_LENGTH = GREEN_DURATION + YELLOW_DURATION + RED_DURATION


def validate_times(times):
    if isinstance(times, (str, bytes)):
        raise TypeError('expected a sequence of integers, not text')
    checked = []
    for value in times:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError('elapsed times must be integers')
        if value < 0:
            raise ValueError('elapsed times must not be negative')
        checked.append(value)
    return checked


def parse_times(text):
    times = []
    for chunk in text.split(','):
        item = chunk.strip()
        if not item:
            continue
        if not item.isdigit():
            raise ValueError('not a valid elapsed time: ' + item)
        times.append(int(item))
    return times


def phase_at(seconds):
    position = seconds % CYCLE_LENGTH
    if position < GREEN_DURATION:
        return 'green', position
    if position < GREEN_DURATION + YELLOW_DURATION:
        return 'yellow', position - GREEN_DURATION
    return 'red', position - GREEN_DURATION - YELLOW_DURATION


def action_at(color, offset):
    if color == 'green':
        return 'go'
    if color == 'yellow':
        return 'slow down'
    if offset >= RED_DURATION - WALK_WINDOW:
        return 'pedestrian walk'
    return 'stop'


def describe(seconds):
    color, offset = phase_at(seconds)
    return color + ': ' + action_at(color, offset)


def traffic_light_actions(times):
    return [describe(seconds) for seconds in validate_times(times)]


def summarize(results):
    walks = sum(1 for line in results if line.endswith('pedestrian walk'))
    return '{0} of {1} events allow a pedestrian walk'.format(walks, len(results))


def main(argv):
    if len(argv) > 1:
        times = parse_times(','.join(argv[1:]))
    else:
        times = [10, 32, 40, 52]
    results = traffic_light_actions(times)
    for seconds, line in zip(times, results):
        print('t={0:>4}s  {1}'.format(seconds, line))
    print(summarize(results))


if __name__ == '__main__':
    import sys

    main(sys.argv)

