def describe(seconds):
    color, offset = phase_at(seconds)
    return color + ": " + action_at(color, offset)


def traffic_light_actions(times):
    return [describe(seconds) for seconds in validate_times(times)]


def summarize(results):
    walks = sum(1 for line in results if line.endswith("pedestrian walk"))
    return "{0} of {1} events allow a pedestrian walk".format(walks, len(results))


def main(argv):
    if len(argv) > 1:
        times = parse_times(",".join(argv[1:]))
    else:
        times = [10, 32, 40, 52]
    results = traffic_light_actions(times)
    for seconds, line in zip(times, results):
        print("t={0:>4}s  {1}".format(seconds, line))
    print(summarize(results))


