def strip_non_digits(raw):
    return ''.join(character for character in raw if character.isdigit())


def mentions_extension(raw):
    return 'extension' in raw.lower()


def format_local(digits):
    return f'{digits[:3]}-{digits[3:]}'


def format_ten(digits):
    area = digits[:3]
    prefix = digits[3:6]
    line = digits[6:]
    return f'({area}) {prefix}-{line}'


def format_one(raw):
    if mentions_extension(raw):
        return 'extension not supported'
    digits = strip_non_digits(raw)
    if len(digits) == 7:
        return format_local(digits)
    if len(digits) == 10:
        return format_ten(digits)
    if len(digits) == 11 and digits.startswith('1'):
        return '+1 ' + format_ten(digits[1:])
    if len(digits) == 12 and digits.startswith('2'):
        return '+2 ' + format_ten(digits[2:])
    return 'invalid number format'


def format_numbers(raw_numbers):
    if isinstance(raw_numbers, str):
        raise TypeError('expected a list of strings, not a single string')
    formatted = []
    for raw in raw_numbers:
        if not isinstance(raw, str):
            raise TypeError('every phone number must be given as a string')
        formatted.append(format_one(raw))
    return formatted


def build_report(raw_numbers):
