def map_genre(genre):
    if genre == 'pop':
        return 'popular'
    if genre == 'rock':
        return 'alternative'
    if genre == 'rap':
        return 'hip hop'
    return genre


def format_duration(seconds):
    minutes, remainder = divmod(seconds, 60)
    return f'{minutes}:{remainder:02d}'


def validate_track(track):
    if len(track) != 4:
        raise ValueError('each track needs an artist, a song, a genre and a duration')
    artist, song, genre, duration = track
    for field in (artist, song, genre):
        if not isinstance(field, str) or not field.strip():
            raise ValueError('artist, song and genre must be non-empty text')
    if not isinstance(duration, int) or isinstance(duration, bool):
        raise ValueError('duration must be a whole number of seconds')
    if duration < 0:
        raise ValueError('duration cannot be negative')
    return artist.strip(), song.strip(), genre, duration


def format_track(track):
    artist, song, genre, duration = validate_track(track)
    label = map_genre(genre)
    time_text = format_duration(duration)
    return f'{artist} - {song} [{label}] {time_text}'


def format_playlist(tracks):
    return [format_track(track) for track in tracks]


def parse_track(record):
    fields = record.split('|')
    if len(fields) != 4:
        raise ValueError('a track record needs four fields separated by a pipe')
    artist, song, genre, duration = fields
    if not duration.strip().isdigit():
        raise ValueError('the duration field must contain digits only')
    return artist, song, genre, int(duration)


def genre_summary(tracks):
    counts = {}
    for track in tracks:
        label = map_genre(validate_track(track)[2])
        counts[label] = counts.get(label, 0) + 1
    parts = []
    for label in sorted(counts):
        parts.append(f'{label} x{counts[label]}')
    return ', '.join(parts)


def total_running_time(tracks):
    return sum(validate_track(track)[3] for track in tracks)


def main():
    records = [
        'queen|bohemian rhapsody|rock|355',
        'michael jackson|billie jean|pop|294',
        'eminem|lose yourself|rap|326',
        'miles davis|so what|jazz|545',
    ]
    playlist = [parse_track(record) for record in records]
    print('playlist')
    for line in format_playlist(playlist):
        print(f'  {line}')
    print(f'genres: {genre_summary(playlist)}')
    print(f'total time: {format_duration(total_running_time(playlist))}')


if __name__ == '__main__':
    main()

