from collections import Counter

BLOOD_GROUPS = (
    'o',
    'a',
    'b',
    'ab',
)

RH_POSITIVE = 'positive'
RH_NEGATIVE = 'negative'
RHESUS_VALUES = (RH_POSITIVE, RH_NEGATIVE)

UNIVERSAL_DONOR_TYPE = 'o negative'
UNIVERSAL_RECIPIENT_TYPE = 'ab positive'


def normalize(text):
    if not isinstance(text, str):
        raise TypeError('blood types must be given as strings')
    return ' '.join(text.lower().split())


def parse_blood_type(text):
    parts = normalize(text).split()
    if len(parts) != 2:
        raise ValueError(f'malformed blood type: {text!r}')
    group, rhesus = parts
    if group not in BLOOD_GROUPS:
        raise ValueError(f'unknown blood group: {group!r}')
    if rhesus not in RHESUS_VALUES:
        raise ValueError(f'unknown rhesus factor: {rhesus!r}')
    return group, rhesus


def canonical(text):
    group, rhesus = parse_blood_type(text)
    return f'{group} {rhesus}'


def classify(donor, recipient):
    donor_type = canonical(donor)
    recipient_type = canonical(recipient)
    if donor_type == UNIVERSAL_DONOR_TYPE:
        return 'universal donor'
    if recipient_type == UNIVERSAL_RECIPIENT_TYPE:
        return 'universal recipient'
    if donor_type == recipient_type:
        return 'exact match'
    if donor_type.endswith(RH_POSITIVE) and recipient_type.endswith(RH_NEGATIVE):
        return 'incompatible rhesus factor'
    return 'standard crossmatch required'


def check_compatibility(pairs):
    return [classify(donor, recipient) for donor, recipient in pairs]


def format_report(pairs, results):
    width = max(len(canonical(donor)) for donor, _ in pairs)
    lines = []
    for (donor, recipient), verdict in zip(pairs, results):
        left = canonical(donor).ljust(width)
        lines.append(f'{left} -> {canonical(recipient):<11} : {verdict}')
    return lines


def summarize(results):
    counts = Counter(results)
    parts = [f'{verdict} x{count}' for verdict, count in sorted(counts.items())]
    return ', '.join(parts)


def main():
    donors = [
        'o negative',
        'B Positive',
        'a negative',
        'ab positive',
        'b negative',
    ]
    recipients = [
        'a positive',
        'ab positive',
        'a negative',
        'o negative',
        'a positive',
    ]
    pairs = list(zip(donors, recipients))
    results = check_compatibility(pairs)
    print('blood donation crossmatch report')
    for line in format_report(pairs, results):
        print(line)
    print(f'summary: {summarize(results)}')


if __name__ == '__main__':
    main()

