def validate_scores(scores):
    for score in scores:
        if not isinstance(score, (int, float)):
            raise TypeError('judge scores must be numeric')
        if score < 0.0 or score > 10.0:
            raise ValueError('judge scores must lie between 0 and 10')


def trimmed_average(scores):
    ordered = sorted(scores)
    kept = ordered[1:-1]
    return sum(kept) / len(kept)


def evaluate_routine(scores):
    validate_scores(scores)
    if not scores:
        return 'no data'
    if any(score == 0.0 for score in scores):
        return 'disqualification'
    if len(scores) < 5:
        return 'invalid routine'
    if all(score == 10.0 for score in scores):
        return 'perfect score'
    average = trimmed_average(scores)
    if average >= 9.5:
        return 'outstanding performance'
    if average >= 8.5:
        return 'excellent routine'
    if average >= 7.0:
        return 'solid effort'
    return 'needs improvement'


def evaluate_routines(routines):
    return [evaluate_routine(scores) for scores in routines]


def parse_scores(text):
    scores = []
    for piece in text.split(','):
        item = piece.strip()
        if item:
            scores.append(float(item))
    return scores


def format_report(routines, evaluations):
    lines = ['Routine scoring report']
    lines.append('-' * 22)
    for index, scores in enumerate(routines, start=1):
        formatted = [f'{score:.1f}' for score in scores]
        shown = ', '.join(formatted)
        if not formatted:
            shown = '(no scores submitted)'
        lines.append(f'{index:>2}. {shown:<30} -> {evaluations[index - 1]}')
    return '\n'.join(lines)


def summarize(evaluations):
    tally = {}
    for label in evaluations:
        tally[label] = tally.get(label, 0) + 1
    parts = [f'{label} x{count}' for label, count in sorted(tally.items())]
    joined = '; '.join(parts)
    return f'Summary: {joined}'


def main():
    raw = '''9.0, 9.5, 9.5, 9.5, 10.0
10.0, 10.0, 10.0, 10.0, 10.0
8.0, 0.0, 9.0, 9.5, 9.0
7.5, 8.0, 8.2

6.0, 6.5, 7.0, 6.8, 7.2
8.6, 8.8, 9.0, 8.4, 9.2'''
    routines = [parse_scores(line) for line in raw.splitlines()]
    evaluations = evaluate_routines(routines)
    print(format_report(routines, evaluations))
    print(summarize(evaluations))


if __name__ == '__main__':
    main()

