LESS_THAN = '<'
LESS_WORD = 'less'
GREATER_THAN = '>'
GREATER_WORD = 'greater'
EMPTY_TEXT = 'empty item'
OPEN_TAG = '<ul>'
CLOSE_TAG = '</ul>'
ITEM_OPEN = '<li>'
ITEM_CLOSE = '</li>'
NEWLINE = '\n'


def replace_symbols(text):
    cleaned = text.replace(LESS_THAN, LESS_WORD)
    return cleaned.replace(GREATER_THAN, GREATER_WORD)


def format_item(text):
    if text == '':
        body = EMPTY_TEXT
    else:
        body = replace_symbols(text)
    return ITEM_OPEN + body + ITEM_CLOSE


def validate_items(items):
    if isinstance(items, str):
        raise TypeError('a single string is not a list of items')
    try:
        candidates = list(items)
    except TypeError:
        raise TypeError('items must be an iterable of strings')
    for candidate in candidates:
        if not isinstance(candidate, str):
            raise TypeError('every item must be a string')
    return candidates


def build_unordered_list(items):
    entries = validate_items(items)
    lines = [OPEN_TAG]
    for entry in entries:
        lines.append(format_item(entry))
    lines.append(CLOSE_TAG)
    return lines


def render_document(lines):
    return NEWLINE.join(lines)


def describe(items):
