import sys
from collections import Counter

LABEL_TERRESTRIAL = 'inner terrestrial'
LABEL_GAS_GIANT = 'gas giant'
LABEL_ICE_GIANT = 'ice giant'
LABEL_DWARF = 'dwarf planet'
LABEL_UNKNOWN = 'unknown celestial body'
REPORT_HEADER = 'planet classification report'

TERRESTRIAL = frozenset((
    'mercury',
    'venus',
    'earth',
    'mars',
))
GAS_GIANTS = frozenset((
    'jupiter',
    'saturn',
))
ICE_GIANTS = frozenset((
    'uranus',
    'neptune',
))
DWARFS = frozenset((
    'pluto',
))
DEFAULT_SAMPLE = (
    'mars',
    'jupiter',
    'sirius',
    'pluto',
    'neptune',
    'earth',
    'saturn',
)


def normalize(name):
    if not isinstance(name, str):
        raise TypeError(f'planet name must be a string, got {type(name).__name__}')
    cleaned = name.strip().lower()
    if not cleaned:
        raise ValueError('planet name must not be empty')
    return cleaned


def classify_planet(name):
    cleaned = normalize(name)
    if cleaned in TERRESTRIAL:
        return LABEL_TERRESTRIAL
    if cleaned in GAS_GIANTS:
        return LABEL_GAS_GIANT
    if cleaned in ICE_GIANTS:
        return LABEL_ICE_GIANT
    if cleaned in DWARFS:
        return LABEL_DWARF
    return LABEL_UNKNOWN


def classify_planets(names):
    return [classify_planet(name) for name in names]


def summarize(labels):
    counts = Counter(labels)
    return sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))


def format_report(names, labels):
    lines = [REPORT_HEADER]
    lines.append('-' * len(REPORT_HEADER))
    for name, label in zip(names, labels):
        lines.append(f'{name}: {label}')
    lines.append('')
    for label, count in summarize(labels):
        lines.append(f'{count} x {label}')
    return '\n'.join(lines)


def main(argv):
    names = [normalize(arg) for arg in argv] or list(DEFAULT_SAMPLE)
    print(format_report(names, classify_planets(names)))


if __name__ == '__main__':
