COIN_UNITS = (
    (25, 'quarter'),
    (10, 'dime'),
    (5, 'nickel'),
    (1, 'penny'),
)


def pluralize(name):
    if name.endswith('y'):
        return name[:-1] + 'ies'
    return name + 's'


def validate_amount(value):
    if not isinstance(value, int):
        raise TypeError('each amount must be an integer number of cents')
    if value < 0:
        raise ValueError('amounts cannot be negative')
    return value


def breakdown(cents):
    remaining = validate_amount(cents)
    counts = []
    for worth, name in COIN_UNITS:
        count = remaining // worth
        remaining -= count * worth
        if count:
            counts.append((count, name))
    return counts


def describe(cents):
    parts = []
    for count, name in breakdown(cents):
        label = pluralize(name) if count > 1 else name
        parts.append('{0} {1}'.format(count, label))
    if not parts:
        return 'no change'
    return ', '.join(parts)


def make_change(amounts):
    return [describe(cents) for cents in amounts]


def parse_amounts(text):
    amounts = []
    for chunk in text.split(','):
        token = chunk.strip()
        if not token:
            raise ValueError('found an empty amount in the input')
        try:
            value = int(token)
        except ValueError:
            raise ValueError('not a whole number of cents: ' + token)
        amounts.append(validate_amount(value))
    return amounts


def format_report(amounts):
    header = 'change breakdown'
    lines = [header, '-' * len(header)]
    for cents, text in zip(amounts, make_change(amounts)):
        lines.append('{0:>5} cents -> {1}'.format(cents, text))
    return lines


def main():
    raw = '31, 0, 99, 5, 141, 25'
    amounts = parse_amounts(raw)
    for line in format_report(amounts):
        print(line)
    coins = sum(item[0] for cents in amounts for item in breakdown(cents))
    print('coins handed out in total: {0}'.format(coins))


if __name__ == '__main__':
    main()

