import math

OCTANTS = (
    'North',
    'North East',
    'East',
    'South East',
    'South',
    'South West',
    'West',
    'North West',
)

SUFFIXES = (
    '\u00b0',
    'degrees',
    'deg',
)


def navigate(degrees):
    try:
        heading = float(degrees)
    except (TypeError, ValueError):
        raise ValueError('heading must be a number') from None
    if not math.isfinite(heading):
        raise ValueError('heading must be a finite value')
    if heading < 0.0 or heading > 360.0:
        raise ValueError(f'heading {heading} is outside the range 0 to 360')
    index = int((heading + 22.5) // 45) % 8
    return OCTANTS[index]


def parse_heading(text):
    cleaned = str(text).strip()
    for suffix in SUFFIXES:
        if cleaned.lower().endswith(suffix):
            cleaned = cleaned[: -len(suffix)].strip()
            break
    if not cleaned:
        raise ValueError('no heading was supplied')
    return float(cleaned)


def abbreviate(name):
    return ''.join(word[0] for word in name.split())


def describe(text):
    heading = parse_heading(text)
    name = navigate(heading)
    return f'{heading:7.2f}  {name:<10} {abbreviate(name)}'


def main():
    readings = [
        '0',
        '22.5',
        '90 deg',
        '180.0\u00b0',
        '247.5',
        '337.5',
        '359.9 degrees',
        '400',
    ]
    print('heading  direction  short')
    for reading in readings:
        try:
            print(describe(reading))
        except ValueError as error:
            print(f'{reading:>7}  rejected: {error}')


if __name__ == '__main__':
    main()

