}


def map(keycode):
    if isinstance(keycode, bool) or not isinstance(keycode, int):
        raise TypeError("keycode must be a plain integer")
    category = _CATEGORIES.get(keycode, "Unknown")
    command = _COMMANDS.get(keycode, "Ignore")
    return category, command


def parse_keycode(text):
    cleaned = text.strip()
    if not cleaned:
        raise ValueError("keycode text must not be blank")
    try:
        return int(cleaned, 0)
    except ValueError:
        raise ValueError(f"unreadable keycode: {cleaned}") from None


def format_binding(keycode):
    category, command = map(keycode)
    return f"0x{keycode:02x}     {category:<9}{command}"


def group_by_category(keycodes):
    groups = {}
    for code in keycodes:
        category, command = map(code)
        groups.setdefault(category, []).append(command)
    return groups


def render_report(keycodes):
    lines = ["keycode  category command"]
    for code in keycodes:
        lines.append(format_binding(code))
    lines.append("--")
    groups = group_by_category(keycodes)
    for category in sorted(groups):
        commands = ", ".join(groups[category])
        lines.append(f"{category}: {commands}")
    return "\n".join(lines)


def main(argv):
    arguments = argv[1:]
    if arguments:
        keycodes = [parse_keycode(item) for item in arguments]
    else:
        keycodes = list(range(9, 21))
    print(render_report(keycodes))
    return 0


if __name__ == "__main__":
    import sys
    raise SystemExit(main(sys.argv))

