AURORAS = 'Auroras'
EXOSPHERE = 'Exosphere'
SATELLITES = 'Satellites'
DEEP_SPACE = 'Deep Space'
VACUUM = 'Vacuum'

LAYERS = [
    (12.0, TROPOSPHERE, WEATHER),
    (50.0, STRATOSPHERE, OZONE),
    (85.0, MESOSPHERE, METEORS),
    (600.0, THERMOSPHERE, AURORAS),
]

DEEP_SPACE_FLOOR = 10000.0

TABLE_HEADER = ' altitude  zone          feature'


def parse_altitude(value):
    if isinstance(value, str):
        text = value.strip()
        try:
            height = float(text)
        except ValueError:
            raise ValueError(f'cannot read an altitude from {text!r}') from None
    else:
        try:
            height = float(value)
        except (TypeError, ValueError):
            raise TypeError('altitude must be a number of kilometers') from None
    if not math.isfinite(height):
        raise ValueError('altitude must be a finite number of kilometers')
    if height < 0.0:
        raise ValueError('altitude cannot reach below sea level')
    return height


def fly(altitude):
    height = parse_altitude(altitude)
    if height > DEEP_SPACE_FLOOR:
        return (DEEP_SPACE, VACUUM)
    for ceiling, zone, feature in LAYERS:
        if height < ceiling:
            return (zone, feature)
    return (EXOSPHERE, SATELLITES)


def describe(altitude):
    height = parse_altitude(altitude)
    zone, feature = fly(height)
    return f'{height:>9.1f}  {zone:<13} {feature}'


def report(altitudes):
    rows = [TABLE_HEADER]
    for altitude in altitudes:
        rows.append(describe(altitude))
    return '\n'.join(rows)


def main(argv):
    altitudes = argv[1:] or [0.5, 25.0, 70.0, 400.0, 3000.0, 42000.0]
    try:
        print(report(altitudes))
    except (TypeError, ValueError) as err:
        print(f'error: {err}', file=sys.stderr)
        return 1
    return 0


if __name__ == '__main__':
