)


def _rest_time(minutes):
    return f'{minutes} minutes'


def cook(temperature):
    if isinstance(temperature, bool) or not isinstance(temperature, int):
        raise TypeError('temperature must be an integer number of degrees')
    if temperature < -459:
        raise ValueError('temperature is below absolute zero')
    for limit, level, minutes in _DONENESS:
        if temperature < limit:
            return level, _rest_time(minutes)
    level, minutes = _OVERDONE
    return level, _rest_time(minutes)


def advise(level):
    if level == 'Raw':
        return 'keep cooking, it is not safe yet'
    if level == 'Well Done':
        return 'serve promptly before it dries out'
    if level == _OVERDONE[0]:
        return 'use a lower heat next time'
    return 'pull it off the heat now'


