DEWEY_CLASSES = (
    'Computer Science and Information',
    'Philosophy and Psychology',
    'Religion',
    'Social Sciences',
    'Language',
    'Pure Science',
    'Technology',
    'Arts and Recreation',
    'Literature',
    'History and Geography',
)


def parse_call_number(text):
    cleaned = text.strip()
    if not cleaned:
        raise ValueError('call number must not be blank')
    try:
        return float(cleaned)
    except ValueError:
        raise ValueError('call number is not numeric: ' + cleaned)


def shelve(decimal):
    value = float(decimal)
    if value != value:
        raise ValueError('call number must be a real number')
    if value < 0:
        raise ValueError('call number must not be negative')
    index = int(value // 100)
    if index >= len(DEWEY_CLASSES):
        raise ValueError('call number exceeds the Dewey range')
    return DEWEY_CLASSES[index]


def parse_record(record):
    parts = record.split('|')
    if len(parts) != 2:
        raise ValueError('record needs a call number and a title: ' + record)
    return parts[0].strip(), parts[1].strip()


def format_entry(number_text, title):
    try:
        number = parse_call_number(number_text)
        subject = shelve(number)
    except ValueError as error:
        return '{0:>9}  {1:<28}  {2}'.format(number_text, title, str(error))
    return '{0:>9.1f}  {1:<28}  {2}'.format(number, title, subject)


def shelf_report(records):
    lines = []
    for record in records:
        number_text, title = parse_record(record)
        lines.append(format_entry(number_text, title))
    return '\n'.join(lines)


def count_by_subject(records):
    tally = {}
    for record in records:
        number_text = parse_record(record)[0]
        try:
            subject = shelve(parse_call_number(number_text))
        except ValueError:
            subject = 'unshelved'
        tally[subject] = tally.get(subject, 0) + 1
    return tally


def main():
    catalog = [
        '005.133 | Programming in Python',
        '150.19 | Schools of Psychology',
        '294.3 | Buddhist Practice',
        '398.2 | Folk Tales of Europe',
        '428.24 | English as a Second Tongue',
        '523.1 | Cosmology for Beginners',
        '641.5 | The Practical Kitchen',
        '796.334 | A History of Football',
        '821.8 | Victorian Verse',
        '940.53 | The Second World War',
        '1200.0 | Catalogue of Oddities',
    ]
    print(shelf_report(catalog))
    print('-' * 68)
    tally = count_by_subject(catalog)
    for subject in sorted(tally):
        print('{0:<32} {1:>3}'.format(subject, tally[subject]))


if __name__ == '__main__':
    main()

