    return CARE_INSTRUCTIONS.get(code, UNKNOWN)


def category(code):
    if code in CARE_INSTRUCTIONS:
        return CATEGORIES[code // 10]
    return 'Unrecognised Symbol'


def parse_tag(text):
    tokens = [token for token in re.split('[,;\\s]+', text.strip()) if token]
    if not tokens:
        raise ValueError('a tag must list at least one care code')
    codes = []
    for token in tokens:
        if not token.isdigit():
            raise ValueError('care codes must be non-negative integers, got ' + token)
        codes.append(int(token))
    return codes


