    lines.extend(format_entry(code) for code in codes)
    unknown = [code for code in codes if code not in CARE_INSTRUCTIONS]
    if unknown:
        listed = ', '.join(str(code) for code in unknown)
        lines.append('Please check the manufacturer for: ' + listed)
    else:
        lines.append('All symbols on this tag are recognised.')
    return '\n'.join(lines)


