    120.0: 'One Twenty Roll',
}


def parse_width(text):
    cleaned = text.strip().lower()
    if cleaned.endswith('mm'):
        cleaned = cleaned[:-2].strip()
    if not cleaned:
        raise ValueError('missing film width measurement')
    try:
        width = float(cleaned)
    except ValueError:
        raise ValueError(f'unreadable film width: {text.strip()}')
    if width <= 0:
        raise ValueError(f'film width must be positive, got {width:g}')
    return width


def develop(width):
    name = EXACT_FORMATS.get(float(width))
    if name is not None:
        return name
    if 100.0 <= width <= 130.0:
        return 'Large Format Sheet'
    return 'Custom Format'


def catalogue(measurements):
    ledger = Counter()
    problems = []
    for raw in measurements:
