def _validate_gradient(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError('gradient must be a number of degrees')
    return float(value)


def _validate_flag(value):
    if isinstance(value, bool):
        return int(value)
    if value not in (0, 1):
        raise ValueError('groomed must be 1 for smoothed snow or 0 for natural terrain')
    return int(value)


def surface_name(groomed):
    if _validate_flag(groomed):
        return 'smoothed snow'
    return 'natural terrain'


def ski(gradient, groomed):
    angle = _validate_gradient(gradient)
    smoothed = _validate_flag(groomed)
    if angle < 0:
        color = 'Invalid Slope'
        shape = 'Closed'
    elif angle < 10:
        color = 'Green Circle'
        shape = 'Beginner'
    elif angle < 20:
        if smoothed:
            color = 'Blue Square'
            shape = 'Intermediate'
        else:
            color = 'Black Diamond'
            shape = 'Advanced'
    elif angle <= 35:
        color = 'Double Black Diamond'
        shape = 'Expert'
    else:
        color = 'Orange Oval'
        shape = 'Extreme Freestyle'
    return color, shape


def format_trail(gradient, groomed):
    color, shape = ski(gradient, groomed)
    template = '{:>6.1f} deg | {:<15s} | {:<21s} | {}'
    return template.format(_validate_gradient(gradient), surface_name(groomed), color, shape)


def report(slopes):
    lines = [format_trail(gradient, groomed) for gradient, groomed in slopes]
    closed = sum(1 for gradient, groomed in slopes if ski(gradient, groomed)[1] == 'Closed')
    if closed:
        lines.append('{} of {} mapped slopes are closed'.format(closed, len(slopes)))
    return lines


def main():
    slopes = [(4.5, 1), (9.9, 0), (12.0, 1), (17.25, 0), (20.0, 1), (35.0, 0), (41.0, 1), (-3.0, 1)]
    print('Resort trail mapping')
    for line in report(slopes):
        print(line)


if __name__ == '__main__':
    main()

