def _validate(temp):
    if isinstance(temp, bool) or not isinstance(temp, int):
        raise TypeError('bean temperature must be an integer in Fahrenheit')
    if temp < -459:
        raise ValueError('bean temperature is below absolute zero')


def roast_name(temp):
    if temp < 380:
        return 'Unroasted'
    if temp <= 400:
        return 'Light Roast'
    if temp <= 415:
        return 'Medium Roast'
    if temp <= 435:
        return 'Medium Dark Roast'
    if temp <= 445:
        return 'Dark Roast'
    if temp <= 475:
        return 'Italian Roast'
    return 'Charcoal'


def flavor_profile(name):
    if name == 'Unroasted':
        return 'Grassy'
    if name == 'Light Roast':
        return 'High Acidity'
    if name == 'Medium Roast':
        return 'Balanced'
    if name == 'Medium Dark Roast':
        return 'Bittersweet'
    if name == 'Dark Roast':
        return 'Smoky'
    if name == 'Italian Roast':
        return 'Burnt'
    return 'Undrinkable'


def roast(temp):
    _validate(temp)
    name = roast_name(temp)
    return name, flavor_profile(name)


def format_report(temp):
    name, flavor = roast(temp)
    return f'{temp:>4}F  {name:<18}{flavor}'


def summarize(temps):
    counts = {}
    for temp in temps:
        name = roast(temp)[0]
        counts[name] = counts.get(name, 0) + 1
    return counts


def main():
    log = [72, 381, 398, 404, 413, 421, 435, 440, 458, 488]
    print('Bean temperature readings')
    for temp in log:
        print(format_report(temp))
    print('-' * 40)
    counts = summarize(log)
    for name in sorted(counts, key=counts.get, reverse=True):
        print(f'{counts[name]:>2} reading(s) landed in {name}')
    peak = max(log)
    print(f'Peak of {peak}F tasted {roast(peak)[1].lower()}')


if __name__ == '__main__':
    main()

