SHAPE_NAMES = {
    1: 'rectangular',
    2: 'symmetrical oval',
    3: 'trapezoid',
    4: 'D subminiature',
    5: 'modular plug',
}

CONNECTOR_TABLE = {
    (4, 1): ('Universal Serial Bus Type A', 'Basic peripherals'),
    (9, 1): ('SuperSpeed Type A', 'Fast peripherals'),
    (24, 2): ('Type C', 'Modern universal'),
    (19, 3): ('High Definition Multimedia Interface', 'Video output'),
    (15, 4): ('Video Graphics Array', 'Analog display'),
    (8, 5): ('Category Six', 'Network routing'),
}


def connect(pins, shape):
    if not isinstance(pins, int) or isinstance(pins, bool):
        raise TypeError('pins must be an integer')
    if not isinstance(shape, int) or isinstance(shape, bool):
        raise TypeError('shape must be an integer')
    if pins < 0:
        raise ValueError('pins cannot be negative')
    return CONNECTOR_TABLE.get((pins, shape), ('Proprietary Connector', 'Unknown use'))


def describe_shape(shape):
    return SHAPE_NAMES.get(shape, 'unclassified shape')


def format_entry(pins, shape):
    technology, use = connect(pins, shape)
    shape_text = describe_shape(shape)
    return '{0:<38} {1:<18} {2} pins, {3}'.format(technology, use, pins, shape_text)


def parse_port(text):
    parts = text.split('/')
    if len(parts) != 2:
        raise ValueError('port spec must look like PINS/SHAPE')
    pins_text, shape_text = (part.strip() for part in parts)
    if not pins_text.isdigit() or not shape_text.isdigit():
        raise ValueError('pins and shape must be written as digits')
    return int(pins_text), int(shape_text)


def build_report(specs):
    lines = ['IT INVENTORY - PORT IDENTIFICATION']
    lines.append('-' * 34)
    unknown = 0
    for spec in specs:
        pins, shape = parse_port(spec)
        technology, _use = connect(pins, shape)
        if technology == 'Proprietary Connector':
            unknown += 1
        lines.append(format_entry(pins, shape))
    lines.append('-' * 34)
    lines.append('Unidentified ports: {0} of {1}'.format(unknown, len(specs)))
    return '\n'.join(lines)


def main():
    inventory = ['4/1', '9/1', '24/2', '19/3', '15/4', '8/5', '13/7']
    print(build_report(inventory))
    try:
        parse_port('usb-c')
    except ValueError as error:
        print('Skipped one entry: {0}'.format(error))


if __name__ == '__main__':
    main()

