def _validate(record):
    if len(record) != 3:
        raise ValueError('each record needs income, age and dependents')
    income, age, dependents = record
    if not isinstance(income, (int, float)):
        raise TypeError('income must be a number')
    if income < 0:
        raise ValueError('income cannot be negative')
    if not isinstance(age, int):
        raise TypeError('age must be an integer')
    if age < 0:
        raise ValueError('age cannot be negative')
    if not isinstance(dependents, int):
        raise TypeError('dependents must be an integer')
    if dependents < 0:
        raise ValueError('dependents cannot be negative')
    return income, age, dependents


def income_bracket(income):
    if income < 30000:
        return 'poverty line'
    if income < 60000:
        return 'working class'
    if income <= 100000:
        return 'middle class'
    return 'upper class'


def profile_tags(income, age, dependents):
    tags = [income_bracket(income)]
    if age > 65:
        tags.append('senior citizen')
    if age < 25:
        tags.append('young adult')
    if dependents == 0:
        tags.append('single filer')
    if dependents >= 3:
        tags.append('large family')
    if income > 100000 and dependents == 0:
        tags.append('luxury tax candidate')
    return tags


def evaluate(records):
    profiles = []
    for record in records:
        income, age, dependents = _validate(record)
        profiles.append(' '.join(profile_tags(income, age, dependents)))
    return profiles


def format_report(records, profiles):
    header = '    INCOME  AGE  DEP  PROFILE'
    lines = [header]
    for (income, age, dependents), profile in zip(records, profiles):
        lines.append(f'{income:>10,}  {age:>3}  {dependents:>3}  {profile}')
    return '\n'.join(lines)


def main():
    records = [
        (20000, 70, 0),
        (45000, 22, 4),
        (78000, 40, 2),
        (150000, 50, 0),
        (120000, 67, 3),
    ]
    profiles = evaluate(records)
    print(format_report(records, profiles))
    flagged = [p for p in profiles if 'luxury tax candidate' in p]
    print(f'luxury tax candidates found: {len(flagged)}')


if __name__ == '__main__':
    main()

