def _normalize(note):
    return ' '.join(str(note).split()).lower()


def _parse(line):
    return [_normalize(part) for part in line.split(',')]


def _family(primary, secondary, tertiary):
    pair = primary + '>' + secondary
    trio = primary + '>' + tertiary
    if pair == 'rose>jasmine':
        return 'floral bouquet'
    if pair == 'lemon>bergamot':
        return 'bright citrus'
    if pair == 'sandalwood>cedar':
        return 'deep woody'
    if pair == 'vanilla>amber':
        return 'oriental sweet'
    if pair == 'lavender>oakmoss':
        return 'aromatic fougere'
    if trio == 'ocean breeze>salt':
        return 'marine aquatic'
    if pair == 'peach>plum':
        return 'fruity lush'
    if trio == 'pepper>clove':
        return 'spicy warm'
    return 'mixed blend'


def classify(perfumes):
    families = []
    for perfume in perfumes:
        notes = [_normalize(note) for note in perfume]
        if len(notes) != 3:
            raise ValueError('a perfume needs primary, secondary and tertiary notes')
        if not all(notes):
            raise ValueError('fragrance notes must not be empty')
        families.append(_family(*notes))
    return families


def describe(perfumes):
    lines = []
    for perfume, family in zip(perfumes, classify(perfumes)):
        label = ', '.join(_normalize(note) for note in perfume)
        lines.append(label + ' -> ' + family)
    return lines


def summarize(perfumes):
    counts = {}
    for family in classify(perfumes):
        counts[family] = counts.get(family, 0) + 1
    order = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return [name + ': ' + str(total) for name, total in order]


def main():
    samples = [
        'rose, jasmine, vanilla',
        'lemon, bergamot, neroli',
        'Sandalwood, Cedar, vetiver',
        'vanilla, amber, tonka',
        'lavender, oakmoss, coumarin',
        'ocean breeze, algae, salt',
        'peach, plum, apricot',
        'pepper, ginger, clove',
        'tobacco, leather, honey',
    ]
