    fields = []
    for field in meal:
        if not isinstance(field, str):
            raise TypeError('meal descriptions must be strings')
        fields.append(field.strip().lower())
    return tuple(fields)


def _recommend(protein, sauce, spice):
    if protein == 'beef':
        if sauce == 'heavy':
            return 'cabernet sauvignon'
        if sauce == 'light':
            return 'pinot noir'
    elif protein == 'chicken':
        if sauce == 'cream':
            return 'chardonnay'
        if sauce == 'tomato':
            return 'sangiovese'
    elif protein == 'fish':
        if sauce == 'citrus':
            return 'sauvignon blanc'
    elif protein == 'pork':
        if spice == 'high':
            return 'riesling'
    elif protein == 'lamb':
        if spice == 'medium':
            return 'syrah'
    elif protein == 'duck':
        if sauce == 'sweet':
            return 'merlot'
    return 'sparkling water'


