from collections import Counter

VALID_TEETH = frozenset((
    'sharp',
    'flat',
    'mixed',
))

VALID_POSTURES = frozenset((
    'bipedal',
    'quadrupedal',
    'aquatic',
))

FIELD_SEPARATOR = ','

RAW_SPECIMENS = (
    'sharp,bipedal,12',
    'sharp,bipedal,4.5',
    'flat,quadrupedal,26',
    'flat,quadrupedal,8',
    'mixed,bipedal,2',
    'flat,bipedal,9',
    'sharp,aquatic,15',
    'mixed,quadrupedal,30',
)


def parse_record(text):
    parts = [field.strip() for field in text.split(FIELD_SEPARATOR)]
    if len(parts) != 3:
        raise ValueError('a record needs teeth, posture and size')
    teeth, posture, raw_size = parts
    try:
        size = float(raw_size)
    except ValueError:
        raise ValueError('size must be a number of meters')
    return teeth.lower(), posture.lower(), size


def classify_one(teeth, posture, size):
    if teeth not in VALID_TEETH:
        raise ValueError('unknown teeth type: ' + teeth)
    if posture not in VALID_POSTURES:
        raise ValueError('unknown posture: ' + posture)
    if size <= 0:
        raise ValueError('size must be positive')
    if posture == 'aquatic':
        if teeth == 'sharp':
            return 'marine predator'
    elif posture == 'bipedal':
        if teeth == 'sharp':
            if size > 10:
                return 'large theropod carnivore'
            return 'small theropod carnivore'
        if teeth == 'mixed':
            if size < 5:
                return 'small omnivore'
        elif size > 5:
            return 'large ornithopod herbivore'
    elif teeth == 'flat':
        if size > 20:
            return 'huge sauropod herbivore'
        return 'medium armored herbivore'
    return 'unclassified specimen'


def classify(dinosaurs):
    return [classify_one(*entry) for entry in dinosaurs]


def format_report(dinosaurs, labels):
    lines = []
    for (teeth, posture, size), label in zip(dinosaurs, labels):
        description = '{0} teeth, {1}, {2:.1f} m'.format(teeth, posture, size)
        lines.append(description.ljust(34) + '-> ' + label)
    return '\n'.join(lines)


def main():
    specimens = [parse_record(record) for record in RAW_SPECIMENS]
    labels = classify(specimens)
    print(format_report(specimens, labels))
    print('-' * 50)
    for label, count in sorted(Counter(labels).items()):
        print('{0:>3} x {1}'.format(count, label))


if __name__ == '__main__':
    main()

