ALLOWED_MILKS = frozenset((
    'cow',
    'goat',
    'sheep',
))


def _normalize_milk(milk):
    if not isinstance(milk, str):
        raise TypeError('milk type must be given as a string')
    cleaned = milk.strip().lower()
    if cleaned not in ALLOWED_MILKS:
        raise ValueError('unsupported milk type: ' + cleaned)
    return cleaned


def _validate(entry):
    moisture, aging, milk = entry
    if not 0 <= moisture <= 100:
        raise ValueError('moisture percentage must lie between 0 and 100')
    if aging < 0:
        raise ValueError('aging months cannot be negative')
    return float(moisture), float(aging), _normalize_milk(milk)


def _classify(moisture, aging, milk):
    if moisture < 30 and aging > 12:
        return 'hard grating cheese'
    if moisture < 40 and aging > 6:
        return 'firm sliceable cheese'
    if 40 <= moisture <= 50 and aging < 6:
        return 'semi soft cheese'
    if moisture > 50 and aging < 1:
        return 'fresh spreadable cheese'
    if moisture > 40 and milk == 'sheep':
        return 'soft rind sheep cheese'
    if moisture > 40 and milk == 'goat':
        return 'fresh goat cheese'
    if moisture < 30 and milk == 'sheep':
        return 'aged pecorino style'
    return 'artisanal mixed cheese'


def categorize(cheeses):
    return [_classify(*_validate(entry)) for entry in cheeses]


def format_report(cheeses):
    header = 'moisture  aging  milk       category'
    lines = [header, '-' * len(header)]
    for entry in cheeses:
        moisture, aging, milk = _validate(entry)
        category = _classify(moisture, aging, milk)
        lines.append(f'{moisture:8.0f}  {aging:5.0f}  {milk:<9}  {category}')
    return '\n'.join(lines)


def summarize(cheeses):
    tally = {}
    for category in categorize(cheeses):
        tally[category] = tally.get(category, 0) + 1
    ranked = sorted(tally.items(), key=lambda item: (-item[1], item[0]))
    rows = [f'{count} x {name}' for name, count in ranked]
    return '\n'.join(rows)


