    wheel_samples = [
        (25, 20, 'cow'),
        (35, 9, 'goat'),
        (62, 0, 'Cow'),
        (55, 8, 'sheep'),
    ]
    print(format_report(wheel_samples))
    print(summarize(wheel_samples))


if __name__ == '__main__':
