HABITATS = (
    'mountain',
    'forest',
    'ocean',
    'abyss',
)


def normalize(record):
    if len(record) != 4:
        raise ValueError('each record needs exactly four fields')
    wings, horns, habitat, fire = record
    place = str(habitat).strip().lower()
    if place not in HABITATS:
        raise ValueError('unsupported habitat: ' + place)
    return bool(wings), bool(horns), place, bool(fire)


def classify(wings, horns, habitat, fire):
    if wings and fire and habitat == 'mountain':
        return 'dragon'
    if wings and not fire and habitat == 'forest':
        return 'fairy'
    if not wings and horns and habitat == 'forest':
        return 'unicorn'
    if not wings and horns and habitat == 'mountain':
        return 'minotaur'
    if not wings and not horns and habitat == 'ocean':
        return 'mermaid'
    if not wings and not horns and habitat == 'forest':
        return 'elf'
    if wings and not horns and habitat == 'mountain':
        return 'griffin'
    if wings and horns and habitat == 'abyss':
        return 'demon'
    return 'unknown beast'


def identify(creatures):
    names = []
    for record in creatures:
        wings, horns, habitat, fire = normalize(record)
        names.append(classify(wings, horns, habitat, fire))
    return names


def describe(record, name):
    wings, horns, habitat, fire = normalize(record)
    traits = []
    if wings:
        traits.append('winged')
    if horns:
        traits.append('horned')
    if fire:
        traits.append('fire-breathing')
    if not traits:
        traits.append('plain')
    joined = ', '.join(traits)
    return '{0} of the {1} ({2})'.format(name, habitat, joined)


def tally(names):
    counts = {}
    for name in names:
        counts[name] = counts.get(name, 0) + 1
    return counts


def main():
    sightings = [
        (True, False, 'mountain', True),
        (True, False, 'Forest', False),
