from collections import Counter


def _validate(index, hero):
    if not isinstance(hero, tuple):
        raise TypeError(f'hero {index} must be a tuple')
    if len(hero) != 3:
        raise ValueError(f'hero {index} must hold strength, speed and energy')
    strength, speed, energy = hero
    if not isinstance(strength, (int, float)) or isinstance(strength, bool):
        raise TypeError(f'hero {index}: lifting strength must be a number')
    if not isinstance(speed, (int, float)) or isinstance(speed, bool):
        raise TypeError(f'hero {index}: flight speed must be a number')
    if not isinstance(energy, bool):
        raise TypeError(f'hero {index}: energy projection must be a boolean')
    if strength < 0:
        raise ValueError(f'hero {index}: lifting strength cannot be negative')
    if speed < 0:
        raise ValueError(f'hero {index}: flight speed cannot be negative')
    return strength, speed, energy


def tier_of(hero, index=0):
    strength, speed, energy = _validate(index, hero)
    if strength > 100 and speed > 10 and energy:
        return 'cosmic tier'
    if strength > 100 and speed < 10 and not energy:
        return 'planetary brute tier'
    if 50 <= strength <= 100 and speed > 5:
        return 'global defender tier'
    if 10 <= strength < 50 and energy:
        return 'city protector tier'
    if strength == 0 and speed == 0 and energy:
        return 'glass cannon mystic'
    if strength < 10 and speed < 1 and not energy:
        return 'street level vigilante'
    if strength > 50 and speed == 0 and not energy:
        return 'heavy tank tier'
    return 'unranked hero'


def classify(heroes):
    if isinstance(heroes, tuple):
        heroes = [heroes]
    return [tier_of(hero, index) for index, hero in enumerate(heroes)]


def format_report(heroes, tiers):
    lines = ['roster classification']
    for hero, tier in zip(heroes, tiers):
        strength, speed, energy = hero
        flag = str(energy).lower()
        lines.append(f'  {strength}t / mach {speed} / energy {flag} -> {tier}')
    lines.append('summary')
    for name, total in sorted(Counter(tiers).items()):
        lines.append(f'  {name}: {total}')
    lines.append(f'  heroes ranked: {len(tiers)}')
    return '\n'.join(lines)


def main():
    roster = [
        (150, 12, True),
        (120, 4, False),
        (75, 8, False),
        (30, 2, True),
        (5, 0.5, False),
        (0, 0, True),
        (60, 0, False),
        (45, 3, False),
    ]
    print(format_report(roster, classify(roster)))


if __name__ == '__main__':
