    if not cleaned:
        raise ValueError('material must not be empty')
    return cleaned


def _unpack(bridge):
    if len(bridge) != 3:
        raise ValueError('each bridge needs span, material and cables')
    span, material, cables = bridge
    if isinstance(span, bool) or not isinstance(span, (int, float)):
        raise TypeError('span must be a number of meters')
    if span < 0:
        raise ValueError('span cannot be negative')
    if not isinstance(cables, bool):
        raise TypeError('suspension cables must be a boolean')
    return float(span), _normalize_material(material), cables


def _classify_one(span, material, cables):
    if material == 'steel' and cables:
        if span > 1000:
            return 'major suspension bridge'
        if span >= 500:
            return 'cable stayed bridge'
    if material == 'steel' and not cables:
        if span < 20:
            return 'simple beam bridge'
        if span < 500:
            return 'steel truss bridge'
    if material == 'wood' and not cables and span < 100:
        return 'covered wooden bridge'
    if material == 'stone' and not cables and span < 50:
        return 'historic masonry arch'
    if material == 'concrete' and not cables and span > 100:
        return 'concrete cantilever bridge'
    return 'custom span'


def classify(bridges):
    results = []
    for bridge in bridges:
        span, material, cables = _unpack(bridge)
        results.append(_classify_one(span, material, cables))
    return results


def _rigging(cables):
    if cables:
        return 'cabled'
    return 'uncabled'


