BOOLEAN_WORDS = {
    'true': True,
    'false': False,
    'yes': True,
    'no': False,
}

FLAG_WORDS = {
    True: 'yes',
    False: 'no',
}

REPORT_HEADER = 'size      freq  multi   tier'


def parse_bucket(text):
    parts = [field.strip() for field in text.split(',')]
    if len(parts) != 3:
        raise ValueError(f'record {text!r} needs three comma separated fields')
    word = parts[2].lower()
    if word not in BOOLEAN_WORDS:
        raise ValueError(f'{parts[2]!r} is not a multi region flag')
    return (int(parts[0]), int(parts[1]), BOOLEAN_WORDS[word])


def validate_bucket(bucket, index):
    if not isinstance(bucket, (tuple, list)) or len(bucket) != 3:
        raise ValueError(f'bucket {index} must hold size, frequency and multi region flag')
    size, frequency, multi_region = bucket
    if isinstance(size, bool) or not isinstance(size, (int, float)):
        raise TypeError(f'bucket {index} has a non numeric size')
    if isinstance(frequency, bool) or not isinstance(frequency, (int, float)):
        raise TypeError(f'bucket {index} has a non numeric access frequency')
    if not isinstance(multi_region, bool):
        raise TypeError(f'bucket {index} needs a boolean multi region flag')
    if size < 0 or frequency < 0:
        raise ValueError(f'bucket {index} cannot use negative measurements')
    return size, frequency, multi_region


def classify(size, frequency, multi_region):
    if size > 10000 and frequency > 1000:
        if multi_region:
            return 'enterprise active global tier'
        return 'enterprise active local tier'
    if size > 1000 and frequency < 10:
        if multi_region:
            return 'deep archive global tier'
        return 'deep archive local tier'
    if size < 1000 and not multi_region:
        if frequency > 100:
            return 'standard frequent access tier'
        if frequency < 10:
            return 'standard infrequent access tier'
    if size < 10 and frequency > 1000 and multi_region:
        return 'edge cached tier'
    return 'unclassified storage tier'


def assign(buckets):
    tiers = []
    for index, bucket in enumerate(buckets):
        size, frequency, multi_region = validate_bucket(bucket, index)
        tiers.append(classify(size, frequency, multi_region))
    return tiers


def format_report(buckets, tiers):
    rows = [REPORT_HEADER]
    for (size, frequency, multi_region), tier in zip(buckets, tiers):
        flag = FLAG_WORDS[multi_region]
        rows.append(f'{size:>8} {frequency:>5} {flag:>6}   {tier}')
    return '\n'.join(rows)


def main():
    records = [
