def _normalize(value, field):
    if not isinstance(value, str):
        raise TypeError(f'{field} must be given as text, got {type(value).__name__}')
    parts = re.split(r'[\s_]+', value.strip().lower())
    return ' '.join(part for part in parts if part)


def _to_bool(value):
    if isinstance(value, bool):
        return value
    text = _normalize(value, 'perspective')
    if text in _TRUE_WORDS:
        return True
    if text in _FALSE_WORDS:
        return False
    raise ValueError(f'cannot read {text!r} as a perspective flag')


_TRUE_WORDS = frozenset({
    'true',
    'yes',
})
_FALSE_WORDS = frozenset({
    'false',
    'no',
})


def _unpack(painting):
    if not isinstance(painting, (tuple, list)):
        raise TypeError('each painting must be a tuple of medium, perspective, subject')
    if len(painting) != 3:
        raise ValueError(f'expected 3 fields per painting, got {len(painting)}')
    medium = _normalize(painting[0], 'medium')
    subject = _normalize(painting[2], 'subject')
    return medium, _to_bool(painting[1]), subject


def parse_entry(line):
    fields = line.split(',')
    if len(fields) != 3:
        raise ValueError(f'expected 3 comma separated fields in {line!r}')
    return _unpack(fields)


def classify(medium, perspective, subject):
    if medium == 'fresco':
        if perspective and subject == 'religion':
            return 'high renaissance religious mural'
        if not perspective and subject == 'nature':
            return 'decorative landscape fresco'
    elif medium == 'oil':
        if perspective and subject == 'portrait':
            return 'formal renaissance portraiture'
        if perspective and subject == 'myth':
            return 'classical mythology canvas'
        if not perspective and subject == 'daily life':
            return 'northern renaissance genre scene'
    elif medium == 'tempera':
        if not perspective and subject == 'religion':
            return 'early renaissance altarpiece'
    elif medium == 'sketch':
        if perspective and subject == 'architecture':
            return 'architectural study'
    return 'uncategorized artwork'


def analyze(paintings):
    styles = []
