def normalize_curve(curve):
    '''Reduce a blade-shape description to one of the four known profiles.'''
    if isinstance(curve, bool):
        if curve:
            return 'curved'
        return 'straight'
    text = str(curve).strip().lower()
    if 'narrow' in text:
        return 'narrow'
    if 'slight' in text:
        return 'slight'
    if 'curv' in text:
        return 'curved'
    if text.startswith('straight'):
        return 'straight'
    if text.startswith('false'):
        return 'straight'
    raise ValueError(f'unrecognised blade profile: {curve!r}')


def sword(blade, edge, curve):
    '''Classify a historical sword from its length, edge count and profile.'''
    length = float(blade)
    edges = int(edge)
    if length <= 0:
        raise ValueError('blade length must be a positive number of inches')
    shape = normalize_curve(curve)
    if shape == 'straight' and edges == 2:
        if 20 <= length < 30:
            return 'gladius'
        if 30 <= length <= 40:
            return 'longsword'
        if length > 40:
            return 'claymore'
    elif shape == 'curved' and edges == 1:
        if 30 <= length <= 40:
            return 'sabre'
        if 20 <= length < 30:
            return 'scimitar'
    elif shape == 'slight' and edges == 1:
        if length > 30:
            return 'katana'
    elif shape == 'narrow' and edges == 2:
        if 30 <= length <= 40:
            return 'rapier'
    return 'unknown weapon'


def parse_spec(spec):
    '''Split a "length, edges, profile" record into usable values.'''
    parts = spec.split(',')
    if len(parts) != 3:
        raise ValueError('a sword spec needs three comma separated fields')
    return float(parts[0]), int(parts[1]), parts[2].strip()


def describe(blade, edge, curve):
    shape = normalize_curve(curve)
    return f'{float(blade):6.1f} {int(edge):>6} {shape:<10} {sword(blade, edge, curve)}'


def main():
    specs = [
        '35, 2, false',
        '24, 2, straight',
        '46, 2, straight',
        '33, 1, curved',
        '27, 1, curved',
        '41, 1, slightly curved',
        '36, 2, very narrow',
        '12, 3, curved',
    ]
    print('length  edges profile    classification')
    for spec in specs:
        blade, edge, curve = parse_spec(spec)
        print(describe(blade, edge, curve))


if __name__ == '__main__':
    main()

