    edges = int(edge)
    if length <= 0:
        raise ValueError("blade length must be a positive number of inches")
    shape = normalize_curve(curve)
    if shape == "straight" and edges == 2:
        if 20 <= length < 30:
            return "gladius"
        if 30 <= length <= 40:
            return "longsword"
        if length > 40:
            return "claymore"
    elif shape == "curved" and edges == 1:
        if 30 <= length <= 40:
            return "sabre"
        if 20 <= length < 30:
            return "scimitar"
    elif shape == "slight" and edges == 1:
        if length > 30:
            return "katana"
    elif shape == "narrow" and edges == 2:
        if 30 <= length <= 40:
            return "rapier"
    return "unknown weapon"


def parse_spec(spec):
    """Split a "length, edges, profile" record into usable values."""
    parts = spec.split(",")
    if len(parts) != 3:
        raise ValueError("a sword spec needs three comma separated fields")
    return float(parts[0]), int(parts[1]), parts[2].strip()


def describe(blade, edge, curve):
    shape = normalize_curve(curve)
    return f"{float(blade):6.1f} {int(edge):>6} {shape:<10} {sword(blade, edge, curve)}"


