}

CUSTOM = 'custom size'


def mattress(width, length):
    for value in (width, length):
        if not isinstance(value, int):
            raise TypeError('dimensions must be given as whole inches')
        if value <= 0:
            raise ValueError('dimensions must be positive')
    return SIZES.get((width, length), CUSTOM)


def parse_dimensions(spec):
    text = spec.strip().lower()
    separator = 'x'
    if separator not in text:
        raise ValueError('expected a spec like 60x80')
    parts = text.split(separator)
    if len(parts) != 2:
        raise ValueError('expected exactly two dimensions')
    try:
        width, length = (int(part.strip()) for part in parts)
    except ValueError:
        raise ValueError('dimensions must be numeric') from None
    return width, length


def describe(spec):
    width, length = parse_dimensions(spec)
    name = mattress(width, length)
    area = width * length / 144.0
    label = name.title() if name != CUSTOM else 'Custom Size'
    return '{0} in x {1} in -> {2} ({3:.1f} sq ft)'.format(width, length, label, area)


def summarize(specs):
