import re
import sys


def normalize(toprow):
    'Reduce a raw top-row description to its first six letters.'
    if not isinstance(toprow, str):
        raise TypeError('toprow must be a string of key labels')
    letters = re.findall('[a-z]', toprow.lower())
    return ''.join(letters[:6])


def keyboard(toprow):
    'Name the keyboard layout implied by the first six top-row letters.'
    key = normalize(toprow)
    if key == 'qwerty':
        return 'standard american'
    if key == 'qwertz':
        return 'central european'
    if key == 'azerty':
        return 'standard french'
    if key == 'dvorak':
        return 'dvorak simplified'
    if key == 'qwfpgj':
        return 'colemak'
    if key == 'xvlcwk':
        return 'bepo'
    if key == 'asdfgh':
        return 'home row testing'
    return 'unrecognized layout'


def spaced(key):
    return ' '.join(key)


def describe(toprow):
    'Build a one-line report for a single top row.'
    key = normalize(toprow)
    layout = keyboard(toprow)
    if not key:
        return f'(no letters) -> {layout}'
    return f'{spaced(key):<13} -> {layout}'


def main(argv):
    rows = argv[1:]
    if not rows:
        rows = [line for line in sys.stdin.read().splitlines() if line.strip()]
    if not rows:
        print('usage: keyboard.py "q w e r t z" ["a z e r t y" ...]')
        return 2
    for row in rows:
        print(describe(row))
    unknown = sum(1 for row in rows if keyboard(row) == 'unrecognized layout')
    if unknown:
        print(f'{unknown} row(s) could not be identified', file=sys.stderr)
        return 1
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

