    'y',
    'overlapping',
))

FALSY = frozenset((
    'false',
    'no',
    'n',
    'separate',
))


def parse_count(slashes):
    if isinstance(slashes, int):
        count = slashes
    else:
        word = normalize(slashes)
        if word.isdigit():
            count = int(word)
        elif word in WORD_NUMBERS:
            count = WORD_NUMBERS[word]
        else:
            raise ValueError(f'unrecognised slash count: {slashes!r}')
    if count < 0:
        raise ValueError('a loaf cannot have a negative number of slashes')
    return count


def normalize_angle(angle):
    word = normalize(angle)
    if word.startswith('right'):
        return 'perpendicular'
    if word.startswith('cross'):
        return 'grid'
    if word in CANONICAL_ANGLES:
        return word
    raise ValueError(f'unrecognised angle description: {angle!r}')


def parse_overlap(overlapping):
    if isinstance(overlapping, bool):
        return overlapping
    word = normalize(overlapping)
    if word in TRUTHY:
        return True
    if word in FALSY:
        return False
    raise ValueError(f'unrecognised overlap flag: {overlapping!r}')


def scoring(slashes, angle, overlapping):
