SPACE = ' '
DASH = '-'
EQUALS = '='
PIPE = '|'
UNITS = dict(zip('one two three four five six seven eight nine'.split(), range(1, 10)))
TENS = dict(zip('twenty thirty forty fifty sixty seventy'.split(), range(20, 80, 10)))
TRUTHY = frozenset('true yes y stepped 1'.split())
FALSY = frozenset('false no n brilliant 0'.split())
ALIAS_RULES = [
    'circle=round',
    'rectangle=rectangular with truncated corners',
    'rectangular=rectangular with truncated corners',
    'square with cut corners=square with truncated corners',
    'oval with points=oval with pointed ends',
    'pear=teardrop',
    'triangle=triangle with flat edges',
]
ALIASES = dict(rule.split(EQUALS, 1) for rule in ALIAS_RULES)


def normalize_shape(shape):
    if not isinstance(shape, str):
        raise TypeError('shape must be given as text')
    text = SPACE.join(shape.lower().replace(DASH, SPACE).split())
    if not text:
        raise ValueError('shape must not be empty')
    return ALIASES.get(text, text)


def parse_facets(facets):
    if isinstance(facets, bool):
        raise TypeError('facets must be a count, not a boolean')
    if isinstance(facets, int):
        return facets
    if not isinstance(facets, str):
        raise TypeError('facets must be a count or a spelled-out number')
    text = facets.lower().replace(DASH, SPACE).strip()
    if text.isdigit():
        return int(text)
    total = 0
    for word in text.split():
        if word in TENS:
            total += TENS[word]
        elif word in UNITS:
            total += UNITS[word]
        else:
            raise ValueError(f'unrecognised number word {word!r}')
    return total


def parse_stepped(stepped):
    if isinstance(stepped, bool):
        return stepped
    text = str(stepped).strip().lower()
    if text in TRUTHY:
        return True
    if text in FALSY:
        return False
    raise ValueError(f'cannot read {stepped!r} as a yes/no value')


def gemcut(shape, facets, stepped):
    outline = normalize_shape(shape)
    count = parse_facets(facets)
    layered = parse_stepped(stepped)
    if outline == 'round' and count == 57 and not layered:
        return 'round brilliant'
    if outline == 'square' and 50 <= count <= 58 and not layered:
        return 'princess cut'
    if outline == 'rectangular with truncated corners' and layered:
        return 'emerald cut'
    if outline == 'square with truncated corners' and layered:
        return 'asscher cut'
    if outline == 'oval with pointed ends' and not layered:
        return 'marquise cut'
    if outline == 'teardrop' and not layered:
        return 'pear cut'
    if outline == 'rounded rectangle' and not layered:
        return 'cushion cut'
    if outline == 'triangle with flat edges':
        return 'trilliant cut'
    return 'fantasy cut'


def describe(shape, facets, stepped):
    verdict = gemcut(shape, facets, stepped)
    return f'{shape} | {facets} facets | stepped={stepped} => {verdict}'


