    samples = [
        'round|57|false',
        'rectangular|50|true',
        'square|fifty eight|no',
        'square with cut corners|49|yes',
        'oval with pointed ends|55|false',
        'pear|58|false',
        'rounded rectangle|64|false',
        'triangle|44|true',
        'heart|59|false',
    ]
    for sample in samples:
        shape, facets, stepped = sample.split(PIPE)
        print(describe(shape, facets, stepped))


if __name__ == '__main__':
