    if grade not in FLEXIBILITIES:
        raise ValueError(f"unknown flexibility {flexibility!r}")
    return grade


def classify_width(width):
    if width <= 0:
        raise ValueError(f"a nib width must be positive, got {width}")
    if width < 0.4:
        return "extra fine"
    for nominal, name in NOMINAL_WIDTHS:
        if abs(width - nominal) <= WIDTH_TOLERANCE:
            return name
    raise ValueError(f"no round nib grade matches {width} mm")


def nib(width, flexibility, flat):
    grade = normalise_flexibility(flexibility)
    if grade == "bent":
        return "fude"
    if flat and grade == "firm":
        return "stub"
    if flat:
        return "italic"
    if grade == "flex":
        return "flex nib"
    return classify_width(width)


def parse_spec(text):
    parts = text.split()
    if len(parts) < 2:
        raise ValueError(f"a nib spec needs a width and a flexibility: {text!r}")
    flat = parts[-1].lower() == "flat"
    try:
        width = float(parts[0])
    except ValueError:
        raise ValueError(f"cannot read a nib width from {parts[0]!r}")
    return width, parts[1], flat


def format_report(text):
    width, flexibility, flat = parse_spec(text)
    shape = "round"
    if flat:
        shape = "flat"
    return f"{width:5.1f} mm  {flexibility:<9} {shape:<6} -> {nib(width, flexibility, flat)}"


def main():
    specs = (
        "0.3 firm",
        "0.5 firm",
        "0.7 firm",
        "0.9 firm",
        "0.6 firm flat",
        "0.6 flexible flat",
        "0.5 flex",
        "0.8 bent",
        "1.4 firm",
    )
    for spec in specs:
        try:
            print(format_report(spec))
        except ValueError as error:
            print(f"{spec}: {error}")


if __name__ == "__main__":
