def _validate(entry):
    if not isinstance(entry, (tuple, list)):
        raise TypeError('each metric must be a tuple of two numbers')
    if len(entry) != 2:
        raise ValueError('each metric needs a plume height and an explosivity index')
    for value in entry:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError('plume height and explosivity index must be numeric')
    height, index = entry
    return float(height), float(index)


def classify(height, index):
    if index < 0:
        return 'invalid data'
    if index <= 1 and height < 2:
        return 'hawaiian'
    if 2 <= index <= 3 and 2 <= height <= 10:
        return 'strombolian'
    if 3 <= index <= 4 and 10 <= height <= 25:
        return 'vulcanian'
    if index >= 4 and height > 25:
        return 'plinian'
    return 'unclassified'


def warning_for(label):
    if label == 'hawaiian':
        return 'lava flow hazard'
    if label == 'strombolian':
        return 'volcanic bomb hazard'
    if label == 'vulcanian':
        return 'heavy ashfall hazard'
    if label == 'plinian':
        return 'extreme devastation hazard'
    return 'no reliable hazard assessment'


def evaluate(metrics):
    if isinstance(metrics, (str, bytes)):
        raise TypeError('metrics must be a list of tuples')
    results = []
    for entry in metrics:
        height, index = _validate(entry)
        label = classify(height, index)
        results.append((label, warning_for(label)))
    return results


def format_report(metrics, results):
    lines = []
    for (height, index), (label, note) in zip(metrics, results):
        column = '{0:>6.1f} km  VEI {1:<4g}'.format(float(height), float(index))
        lines.append('{0} -> {1} ({2})'.format(column, label, note))
    return '\n'.join(lines)


