PREFIX = 'mount type is'
SEPARATOR = '/'


def normalize(text):
    if not isinstance(text, str):
        raise TypeError('every spec field must be a string')
    cleaned = ' '.join(text.strip().lower().split())
    if not cleaned:
        raise ValueError('spec fields must not be empty')
    return cleaned


def parse_spec(spec):
    if isinstance(spec, str):
        raise TypeError('a spec must be a pair, not a single string')
    fields = list(spec)
    if len(fields) != 2:
        raise ValueError('a spec must hold exactly two fields')
    return normalize(fields[0]), normalize(fields[1])


def split_pair(line):
    parts = line.split(SEPARATOR)
    if len(parts) != 2:
        raise ValueError('a spec line needs exactly one separator')
    return parts[0], parts[1]


def match_style(tracking, use):
    if tracking == 'none':
        return 'stationary mount'
    if tracking == 'manual':
        if use == 'deep sky':
            return 'dobsonian mount'
        if use == 'terrestrial':
            return 'altazimuth mount'
    elif tracking == 'motorized':
        if use == 'astrophotography':
            return 'equatorial mount'
    elif tracking == 'computerized':
        if use == 'planetary':
            return 'fork mount'
    return 'custom mount'


def describe(style):
    return f'{PREFIX} {style}'


def classify(specs):
    if isinstance(specs, str):
        raise TypeError('specs must be a sequence of pairs')
    results = []
    for spec in specs:
        tracking, use = parse_spec(spec)
        results.append(describe(match_style(tracking, use)))
    return results


def format_report(specs, results):
    lines = ['tracking / use -> classification']
    for spec, result in zip(specs, results):
        tracking, use = parse_spec(spec)
        lines.append(f'{tracking} {SEPARATOR} {use} -> {result}')
    return '\n'.join(lines)


def main():
    raw_lines = [
        'Manual / deep sky',
        'motorized / Astrophotography',
        'manual / terrestrial',
        'computerized / planetary',
        'none / solar',
        'motorized / terrestrial',
    ]
    catalog = [split_pair(line) for line in raw_lines]
    report = format_report(catalog, classify(catalog))
    print(report)
    unmatched = sum(1 for line in report.splitlines() if line.endswith('custom mount'))
    print(f'unclassified configurations: {unmatched}')


if __name__ == '__main__':
    main()

