    'outward',
    'hidden',
    'flat',
)

CREASES = (
    'sharp',
    'soft',
    'none',
)

SEPARATORS = ',-/'


def tokenize(text):
    cleaned = text.lower()
    for symbol in SEPARATORS:
        cleaned = cleaned.replace(symbol, ' ')
    return cleaned.split()


def find_direction(tokens):
    for token in tokens:
        if token in DIRECTIONS:
            return token
    return 'flat'


def find_crease(tokens):
    for token in tokens:
        if token in CREASES:
            return token
    return 'none'


def classify(direction, crease):
    if crease == 'none':
        return 'unfold step'
    if crease == 'sharp':
        if direction == 'inward':
            return 'valley fold'
        if direction == 'outward':
            return 'mountain fold'
        if direction == 'hidden':
            return 'inside reverse fold'
    if crease == 'soft':
        if direction == 'flat':
            return 'squash fold'
        if direction == 'outward':
            return 'petal fold'
    return 'generic fold'


def describe(step):
    if not isinstance(step, str):
        raise TypeError('each step must be given as text')
    tokens = tokenize(step)
    move = classify(find_direction(tokens), find_crease(tokens))
    return 'step requires ' + move


def process(steps):
    return [describe(step) for step in steps]


def report(steps):
    lines = []
    for number, instruction in enumerate(process(steps), start=1):
        lines.append(f'{number}. {instruction}')
    return '\n'.join(lines)


