PREFIX = 'geographical feature detected'

VALID_LOCATIONS = (
    'mountain',
    'valley',
    'ocean',
    'continent',
)


def normalize(location):
    if not isinstance(location, str):
        raise TypeError('location must be given as text')
    cleaned = location.strip().lower()
    if cleaned not in VALID_LOCATIONS:
        raise ValueError('unknown location: ' + cleaned)
    return cleaned


def parse_depth(depth):
    if isinstance(depth, bool):
        raise TypeError('depth must be a number in meters')
    if isinstance(depth, str):
        depth = depth.strip()
    try:
        value = float(depth)
    except (TypeError, ValueError):
        raise ValueError('depth is not a valid measurement')
    if value < 0:
        raise ValueError('depth cannot be negative')
    return value


def classify(location, depth):
    if location == 'mountain' and depth < 100:
        return 'cirque glacier'
    if location == 'valley' and depth > 200:
        return 'valley glacier'
    if location == 'ocean' and depth > 50:
        return 'tidewater glacier'
    if location == 'continent':
        if depth > 1000:
            return 'ice sheet'
        if depth < 1000:
            return 'ice cap'
    return 'anomalous ice formation'


def analyze(formations):
    results = []
    for formation in formations:
        location, depth = formation
        kind = classify(normalize(location), parse_depth(depth))
        results.append(PREFIX + ' ' + kind)
    return results


def report(formations):
    lines = []
    for formation, identification in zip(formations, analyze(formations)):
        label = '{0} at {1} m'.format(formation[0], formation[1])
        lines.append(label.ljust(24) + '-> ' + identification)
    return '\n'.join(lines)


def main():
    survey = [
        ('mountain', 90),
        ('valley', 250),
        ('ocean', 75),
        ('continent', 1500),
        ('continent', 400),
        ('mountain', 320),
    ]
    print(report(survey))
    try:
        analyze([('tundra', 10)])
    except ValueError as error:
        print('survey rejected: {0}'.format(error))


if __name__ == '__main__':
    main()

