text_nat:
VALID_FRAMES = (
    'vertical',
    'horizontal',
    'none',
)

VALID_EXPANSIONS = (
    'stacking',
    'lateral',
    'nadiring',
    'none',
)


def _normalize(value):
    if not isinstance(value, str):
        raise TypeError('frame and expansion must be given as text')
    return ' '.join(value.lower().split())


def _parse_pair(item):
    if isinstance(item, str):
        if ',' in item:
            parts = item.split(',')
        else:
            parts = item.split(' and ')
    else:
        parts = list(item)
    if len(parts) != 2:
        raise ValueError('each apiary needs one frame text and one expansion text')
    frame = _normalize(parts[0])
    expansion = _normalize(parts[1])
    if frame not in VALID_FRAMES:
        raise ValueError(f'unknown frame orientation: {frame}')
    if expansion not in VALID_EXPANSIONS:
        raise ValueError(f'unknown expansion method: {expansion}')
    return frame, expansion


def _hive_name(frame, expansion):
    if frame == 'vertical':
        if expansion == 'stacking':
            return 'langstroth hive'
        if expansion == 'nadiring':
            return 'warre hive'
        if expansion == 'lateral':
            return 'long langstroth hive'
    elif frame == 'horizontal':
        if expansion == 'lateral':
            return 'top bar hive'
    elif frame == 'none':
        if expansion == 'none':
            return 'traditional skep'
    return 'experimental hive design'


def _hive_note(hive):
    if hive.endswith('langstroth hive'):
        return 'optimal for honey extraction'
    return 'optimal for natural comb'


def evaluate(apiaries):
    verdicts = []
    for item in apiaries:
        frame, expansion = _parse_pair(item)
        hive = _hive_name(frame, expansion)
        verdicts.append(f'{hive} {_hive_note(hive)}')
    return verdicts


def format_report(apiaries):
    lines = []
    for item, verdict in zip(apiaries, evaluate(apiaries)):
        frame, expansion = _parse_pair(item)
        lines.append(f'{frame:<10} {expansion:<9} -> {verdict}')
    return '\n'.join(lines)


def main():
    apiaries = [
        'horizontal and lateral',
        'vertical, stacking',
        'vertical and nadiring',
        'none and none',
        'vertical and lateral',
        'horizontal and nadiring',
    ]
    print(format_report(apiaries))


if __name__ == '__main__':
    main()

