from collections import Counter

PREFIX = 'turbine classification shows'

AXES = (
    'horizontal',
    'vertical',
)

BLADES = (
    'lift',
    'drag',
    'hybrid',
)

SEPARATOR = ','
JOINER = ', '
LABEL_FORMAT = '{0}/{1}'
NOTE_FORMAT = ' [unrecognised: {0}]'
LINE_FORMAT = '{0:<24} -> {1}{2}'
TALLY_FORMAT = '{0:<24} {1}'


def normalize(value):
    if not isinstance(value, str):
        raise TypeError('every turbine field must be supplied as text')
    cleaned = value.strip().lower()
    if not cleaned:
        raise ValueError('turbine fields must not be blank')
    return cleaned


def unpack(entry):
    fields = tuple(entry)
    if len(fields) != 2:
        raise ValueError('a turbine is described by an axis and a blade shape')
    return normalize(fields[0]), normalize(fields[1])


def parse_spec(spec):
    return unpack(normalize(spec).split(SEPARATOR))


def classify(axis, blade):
    if axis == 'horizontal':
        if blade == 'lift':
            return 'traditional hawt'
        if blade == 'drag':
            return 'historical windmill'
    elif axis == 'vertical':
        if blade == 'drag':
            return 'savonius rotor'
        if blade == 'lift':
            return 'darrieus rotor'
        if blade == 'hybrid':
            return 'giromill design'
    return 'experimental turbine'


def odd_terms(axis, blade):
    flagged = []
    if axis not in AXES:
        flagged.append(axis)
    if blade not in BLADES:
        flagged.append(blade)
    return flagged


def assess(turbines):
    verdicts = []
    for entry in turbines:
        axis, blade = unpack(entry)
        verdicts.append('{0} {1}'.format(PREFIX, classify(axis, blade)))
    return verdicts


def report(turbines):
    pairs = [unpack(entry) for entry in turbines]
    lines = []
    for (axis, blade), verdict in zip(pairs, assess(turbines)):
        note = ''
        flagged = odd_terms(axis, blade)
        if flagged:
            note = NOTE_FORMAT.format(JOINER.join(flagged))
        label = LABEL_FORMAT.format(axis, blade)
        lines.append(LINE_FORMAT.format(label, verdict, note))
    tally = Counter(classify(axis, blade) for axis, blade in pairs)
    lines.append('-' * 60)
    for kind in sorted(tally):
        lines.append(TALLY_FORMAT.format(kind, tally[kind]))
    return '\n'.join(lines)


def main():
    fleet = [
        'horizontal, lift',
        'vertical, drag',
        'vertical, lift',
        'vertical, hybrid',
        'horizontal, drag',
        'diagonal, sail',
    ]
    print(report([parse_spec(spec) for spec in fleet]))


if __name__ == '__main__':
    main()

