text_nat:
CRYSTALLINE = 'crystalline glaze'
RAKU = 'raku crackle glaze'
GLOSS = 'standard gloss glaze'
MATTE = 'matte reduction glaze'
CRAWLING = 'crawling glaze effect'
UNPREDICTABLE = 'unpredictable glaze outcome'
SPECIAL_NOTE = 'requires special handling'

VALID_COOLING = (
    'fast',
    'slow',
    'moderate',
)

SPECIAL_GLAZES = (
    CRYSTALLINE,
    RAKU,
)


def validate_temperature(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError('firing temperature must be a number in celsius')
    if value <= 0:
        raise ValueError('firing temperature must be greater than zero')
    return float(value)


def normalise_cooling(text):
    if not isinstance(text, str):
        raise TypeError('cooling rate must be given as text')
    cooling = text.strip().lower()
    if cooling not in VALID_COOLING:
        raise ValueError(f'unsupported cooling rate: {text!r}')
    return cooling


def classify(temperature, cooling):
    if temperature > 1200 and cooling == 'slow':
        return CRYSTALLINE
    if temperature < 1000 and cooling == 'fast':
        return RAKU
    if 1000 <= temperature <= 1200 and cooling == 'moderate':
        return GLOSS
    if temperature > 1200 and cooling == 'fast':
        return MATTE
    if temperature < 1000 and cooling == 'slow':
        return CRAWLING
    return UNPREDICTABLE


def describe(kilns):
    descriptions = []
    for position, kiln in enumerate(kilns, start=1):
        if len(kiln) != 2:
            raise ValueError(f'kiln {position} needs a temperature and a cooling rate')
        temperature = validate_temperature(kiln[0])
        cooling = normalise_cooling(kiln[1])
        glaze = classify(temperature, cooling)
        if glaze in SPECIAL_GLAZES:
            glaze = f'{glaze} {SPECIAL_NOTE}'
        descriptions.append(glaze)
    return descriptions


def format_report(kilns, descriptions):
    heading = 'kiln firing results'
    lines = [heading, '=' * len(heading)]
    for (temperature, cooling), description in zip(kilns, descriptions):
        rate = normalise_cooling(cooling)
        lines.append(f'{temperature:>6.0f}C  {rate:<9}{description}')
    return '\n'.join(lines)


def main():
    kilns = [
        (900, 'fast'),
        (1250, 'Slow'),
        (1100, 'moderate'),
        (1300, 'fast'),
        (850, 'slow'),
        (1150, 'fast'),
    ]
    print(format_report(kilns, describe(kilns)))


if __name__ == '__main__':
    main()

