text_nat:
POSITIONS = (
    'standing',
    'seated',
    'supine',
    'prone',
)

ACTIONS = (
    'bend',
    'twist',
    'balance',
    'inversion',
)

BREATH_CUE = 'focus on breath'
TRANSITIONAL = 'transitional movement'


def normalize(text):
    return text.strip().lower()


def parse_pose(entry):
    if isinstance(entry, str):
        parts = entry.split(',')
    else:
        parts = list(entry)
    if len(parts) != 2:
        raise ValueError(f'a pose needs exactly a position and an action: {entry!r}')
    return normalize(parts[0]), normalize(parts[1])


def validate(position, action):
    if position not in POSITIONS:
        raise ValueError(f'unknown body position: {position}')
    if action not in ACTIONS:
        raise ValueError(f'unknown primary action: {action}')


def label_for(position, action):
    if position == 'standing':
        if action == 'balance':
            return 'tree pose variation'
        if action == 'bend':
            return 'forward fold'
    elif position == 'seated':
        if action == 'twist':
            return 'half lord of the fishes'
    elif position == 'prone':
        if action == 'bend':
            return 'cobra or bow pose'
    elif position == 'supine':
        if action == 'inversion':
            return 'shoulder stand'
    return TRANSITIONAL


def classify(poses):
    results = []
    for entry in poses:
        position, action = parse_pose(entry)
        validate(position, action)
        results.append(f'{label_for(position, action)} {BREATH_CUE}')
    return results


def format_report(poses, results):
    lines = []
    for entry, result in zip(poses, results):
        position, action = parse_pose(entry)
        lines.append(f'{position} + {action} -> {result}')
    return '\n'.join(lines)


def summarize(results):
    unmatched = sum(1 for result in results if result.startswith(TRANSITIONAL))
    return f'{unmatched} of {len(results)} entries fell back to {TRANSITIONAL}'


def main():
    sequence = [
        'standing, balance',
        'seated, twist',
        'prone, bend',
        'supine, inversion',
        'standing, bend',
        'supine, twist',
    ]
    results = classify(sequence)
    print(format_report(sequence, results))
    print(summarize(results))


if __name__ == '__main__':
    main()

