            return "shoulder stand"
    return TRANSITIONAL


def classify(poses):
    results = []
    for entry in poses:
        position, action = parse_pose(entry)
        validate(position, action)
        results.append(f"{label_for(position, action)} {BREATH_CUE}")
    return results


def format_report(poses, results):
    lines = []
    for entry, result in zip(poses, results):
        position, action = parse_pose(entry)
        lines.append(f"{position} + {action} -> {result}")
    return "\n".join(lines)


def summarize(results):
    unmatched = sum(1 for result in results if result.startswith(TRANSITIONAL))
    return f"{unmatched} of {len(results)} entries fell back to {TRANSITIONAL}"


def main():
    sequence = [
        "standing, balance",
        "seated, twist",
        "prone, bend",
        "supine, inversion",
        "standing, bend",
        "supine, twist",
    ]
    results = classify(sequence)
    print(format_report(sequence, results))
    print(summarize(results))


if __name__ == "__main__":
    main()

