MAX_SCORE = 10


def parse_metrics(raw):
    parts = [piece.strip() for piece in raw.split(',')]
    if len(parts) != 3:
        raise ValueError('exactly three metrics are required')
    numbers = []
    for part in parts:
        if not part.lstrip('-').isdigit():
            raise ValueError('metrics must be whole numbers')
        numbers.append(int(part))
    return numbers


def validate(metrics):
    if any(value < 0 for value in metrics):
        return 'negative values not allowed'
    age, violence, language = metrics
    if violence > MAX_SCORE or language > MAX_SCORE:
        return 'maximum score exceeded'
    return None


def is_perfect(violence, language):
    return violence == 0 and language == 0


def classify(age, violence, language):
    if age < 8:
        return 'general audiences'
    if age < 13 and violence < 4:
        return 'parental guidance'
    if violence >= 9:
        return 'restricted viewing'
    if language >= 9:
        return 'adults only'
    if age < 15:
        return 'teen viewing'
    if age < 18:
        return 'mature audiences'
    return 'unrestricted access'


def evaluate(metrics):
    problem = validate(metrics)
    if problem is not None:
        return problem
    age, violence, language = metrics
    if is_perfect(violence, language):
        return 'completely family friendly'
    return classify(age, violence, language)


def report(raw):
    try:
        metrics = parse_metrics(raw)
    except ValueError as error:
        return 'invalid input ({0})'.format(error)
    return '{0} -> {1}'.format(raw, evaluate(metrics))


