def _immediate_boarding(needs_assistance, with_infants):
    if needs_assistance:
        return 'priority medical'
    if with_infants:
        return 'family boarding'
    return None


def _by_mileage(miles, first_class):
    if first_class and miles > 100000:
        return 'priority elite'
    if first_class:
        return 'priority standard'
    if miles > 50000:
        return 'premium frequent flyer'
    if miles > 25000:
        return 'preferred main cabin'
    if miles > 10000:
        return 'main cabin early'
    return 'main cabin late'


def _unpack(passenger):
    if len(passenger) != 4:
        raise ValueError('passenger record must hold exactly four fields')
    miles, first_class, needs_assistance, with_infants = passenger
    if not isinstance(miles, int) or isinstance(miles, bool):
        raise TypeError('mileage must be an integer')
    for flag in (first_class, needs_assistance, with_infants):
        if not isinstance(flag, bool):
            raise TypeError('class and service fields must be booleans')
    return miles, first_class, needs_assistance, with_infants


def assign(passenger):
    miles, first_class, needs_assistance, with_infants = _unpack(passenger)
    if miles < 0:
        return 'invalid mileage amount'
    if first_class and needs_assistance:
        return 'special handling required'
    immediate = _immediate_boarding(needs_assistance, with_infants)
    if immediate is not None:
        return immediate
    return _by_mileage(miles, first_class)


def describe(passenger):
    miles, first_class, needs_assistance, with_infants = _unpack(passenger)
    traits = []
    if first_class:
        traits.append('first class')
    if needs_assistance:
        traits.append('assistance')
    if with_infants:
        traits.append('infants')
    if not traits:
        traits.append('no special needs')
    separator = ', '
    return '{:>7} mi ({})'.format(miles, separator.join(traits))


def boarding_report(manifest):
    lines = []
    for passenger in manifest:
        template = '{} -> {}'
        lines.append(template.format(describe(passenger), assign(passenger)))
    return '\n'.join(lines)


