def parse_conditions(conditions):
    if len(conditions) != 2:
        raise ValueError('expected exactly two soil measurements')
    nitrogen, ph = conditions
    for value in (nitrogen, ph):
        if not isinstance(value, int):
            raise TypeError('soil measurements must be integers')
    return nitrogen, ph


def is_neutral_soil(nitrogen, ph):
    return ph == 7 and nitrogen == 0


def rotate(conditions):
    nitrogen, ph = parse_conditions(conditions)
    if nitrogen < 0 or ph < 0:
        return 'invalid soil measurements'
    if ph > 14:
        return 'extremely alkaline soil'
    if is_neutral_soil(nitrogen, ph):
        return 'resting cover crops'
    if nitrogen < 10 and ph > 7:
        return 'leguminous crops'
    if nitrogen > 50 and ph < 6:
        return 'brassica crops'
    if 10 <= nitrogen <= 20 and ph < 6:
        return 'root vegetables'
    if 20 <= nitrogen <= 30:
        return 'nightshade plants'
    if 30 <= nitrogen <= 40:
        return 'allium family'
    if nitrogen > 40 and ph == 7:
        return 'cucurbit vines'
    return 'leafy greens'


def describe(conditions):
    nitrogen, ph = parse_conditions(conditions)
    return 'N={0} pH={1} -> {2}'.format(nitrogen, ph, rotate(conditions))


def plan_report(plots):
    lines = ['seasonal rotation plan']
    for name, conditions in plots:
        try:
            outcome = describe(conditions)
        except (TypeError, ValueError) as error:
            outcome = 'unusable reading ({0})'.format(error)
        lines.append('{0}: {1}'.format(name, outcome))
    return '\n'.join(lines)


