    parts = [piece.strip() for piece in text.split(',')]
    if len(parts) != 3:
        raise ValueError('expected weight, soil level and delicate flag')
    weight = int(parts[0])
    soil = int(parts[1])
    delicate = parts[2].lower() == 'true'
    return [weight, soil, delicate]


def special_care(weight):
    if weight < 3:
        return 'delicate cold wash'
    return 'wool safe wash'


def calculate(laundry):
    weight, soil, delicate = laundry
    if weight < 0:
        return 'impossible weight provided'
    if soil < 1 or soil > 10:
        return 'invalid soil rating'
    if delicate:
        return special_care(weight)
    if soil == 10 and weight > 8:
        return 'intensive hot wash'
    if soil > 7 and weight > 5:
        return 'heavy load extra'
    if soil < 3 and weight < 3:
        return 'quick wash minimal'
    if soil < 3 and weight > 5:
        return 'light load regular'
    if weight > 10:
        return 'extra large maximum'
    return 'synthetic warm cycle'


def describe(laundry):
    weight, soil, delicate = laundry
    fabric = 'standard'
    if delicate:
        fabric = 'delicate'
    return f'{weight} kg, soil {soil}, {fabric}'


def report(lines):
    rows = []
    for line in lines:
        load = parse_load(line)
        rows.append(f'{describe(load):<28} -> {calculate(load)}')
