        return 'moisture exceeds maximum'
    if protein == 0:
        return 'pure cornstarch'
    return None


def substitute(requirements):
    gluten_free, nut_allergy, protein, moisture = _validate(requirements)
    extreme = _extreme_case(protein, moisture)
