def parse_status(text):
    parts = [item.strip() for item in text.split(',')]
    if len(parts) != 3:
        raise ValueError('status needs energy, days and joint pain')
    energy = int(parts[0])
    days = int(parts[1])
    flag = parts[2].lower()
    if flag == 'true':
        pain = True
    elif flag == 'false':
        pain = False
    else:
        raise ValueError('joint pain must be true or false')
    return [energy, days, pain]


