        return 'invalid time elapsed'
    recovery = recovery_plan(days, joint_pain)
    if recovery is not None:
        return recovery
    if energy > 8:
        if days < 3:
            return 'high intensity intervals'
        return 'heavy lower body power'
    if energy >= 5:
        if days < 3:
            return 'steady state cardio'
        return 'upper body strength'
    if days < 2:
        return 'core stability routine'
    return 'full body circuit'


def format_report(status, workout):
    energy, days, joint_pain = status
    note = 'sore joints'
    if not joint_pain:
        note = 'healthy joints'
    return 'energy {0}, rest {1}d, {2} -> {3}'.format(energy, days, note, workout)


