TEXTURES = {
    'fluffy': True,
    'smooth': False,
}


def parse_yarn(spec):
    parts = [part.strip() for part in spec.split(',')]
    if len(parts) != 3:
        raise ValueError('expected stitches, plies and texture')
    stitches, plies, texture = parts
    key = texture.lower()
    if key not in TEXTURES:
        raise ValueError(f'unknown texture {texture!r}')
    return [int(stitches), int(plies), TEXTURES[key]]


def special_texture(stitches, fluffy):
    if fluffy and stitches < 3:
        return 'novelty boucle yarn'
    return None


def categorize(yarn):
    stitches, plies, fluffy = yarn
    if stitches < 0 or plies < 0:
        return 'negative values prohibited'
    if plies > 20:
        return 'uncommonly high plies'
    novelty = special_texture(stitches, fluffy)
    if novelty is not None:
        return novelty
    if stitches > 30:
        return 'cobweb lace weight'
    if stitches >= 20:
        return 'standard lace weight'
    if stitches >= 15:
        return 'fingering weight sock yarn'
    if stitches >= 11:
        return 'sport weight baby yarn'
    if stitches >= 8:
        return 'worsted weight afghan yarn'
    if stitches >= 5:
        return 'bulky weight winter yarn'
    return 'super bulky jumbo yarn'


def describe(spec):
    yarn = parse_yarn(spec)
    stitches, plies, fluffy = yarn
    if plies == 1:
        unit = 'ply'
    else:
        unit = 'plies'
    if fluffy:
        finish = 'fluffy'
    else:
        finish = 'smooth'
    return f'{stitches} spi / {plies} {unit} / {finish} -> {categorize(yarn)}'


