def _parse(ingredients):
    if len(ingredients) != 3:
        raise ValueError('blend expects oil, vinegar and dairy')
    oil, vinegar, dairy = ingredients
    if isinstance(oil, bool) or not isinstance(oil, int):
        raise TypeError('oil percentage must be an integer')
    if isinstance(vinegar, bool) or not isinstance(vinegar, int):
        raise TypeError('vinegar percentage must be an integer')
    if not isinstance(dairy, bool):
        raise TypeError('dairy flag must be a boolean')
    return oil, vinegar, dairy


def dairy_blend(oil):
    if oil > 50:
        return 'creamy classic ranch'
    return 'tangy blue cheese'


def vinaigrette(oil, vinegar):
    if oil > 70 and vinegar < 20:
        return 'mild olive oil dressing'
    if 50 <= oil <= 70 and vinegar > 20:
        return 'sharp balsamic vinaigrette'
    if oil < 50 and vinegar > 40:
        return 'acidic red wine vinaigrette'
    if oil == 50 and vinegar == 50:
        return 'perfectly balanced emulsion'
    if oil < 20:
        return 'light citrus splash'
    return 'standard house vinaigrette'


def blend(ingredients):
    oil, vinegar, dairy = _parse(ingredients)
    if oil < 0 or vinegar < 0:
        return 'invalid negative percentages'
    if oil + vinegar > 100:
        return 'proportions exceed maximum'
    if dairy:
        return dairy_blend(oil)
    return vinaigrette(oil, vinegar)


def format_report(ingredients):
    oil, vinegar, dairy = _parse(ingredients)
    if dairy:
        dairy_label = 'with dairy'
    else:
        dairy_label = 'dairy free'
    recipe = blend(ingredients)
    return '{0:>4}% oil / {1:>4}% vinegar, {2:<10} -> {3}'.format(oil, vinegar, dairy_label, recipe)


def main():
    samples = [
