def _validate(skin):
    if len(skin) != 3:
        raise ValueError('skin needs an oiliness level, a sensitivity level and a morning flag')
    oiliness, sensitivity, morning = skin
    if not isinstance(oiliness, int) or isinstance(oiliness, bool):
        raise TypeError('oiliness must be an integer')
    if not isinstance(sensitivity, int) or isinstance(sensitivity, bool):
        raise TypeError('sensitivity must be an integer')
    if not isinstance(morning, bool):
        raise TypeError('the morning routine flag must be a boolean')
    return oiliness, sensitivity, morning


def morning_care(sensitivity):
    if sensitivity > 7:
        return 'gentle mineral daily sunscreen'
    return 'lightweight chemical sunscreen'


def evening_care(oiliness, sensitivity):
    if oiliness > 8 and sensitivity < 4:
        return 'strong exfoliating acid toner'
    if oiliness > 8 and sensitivity > 7:
        return 'soothing salicylic wash'
    if oiliness < 4 and sensitivity < 4:
        return 'thick rich night moisturizer'
    if oiliness < 4 and sensitivity > 7:
        return 'hypoallergenic repairing ceramide cream'
    if oiliness == 5 and sensitivity == 5:
        return 'balanced hydrating face serum'
    return 'mild purifying clay mask'


def build(skin):
    oiliness, sensitivity, morning = _validate(skin)
    if oiliness < 0 or sensitivity < 0:
        return 'levels cannot be negative'
