PREFIX = 'attention passengers'

SCHEDULE_TEXT = '''
Northline 0
Eastbound 4
Coast Express 12
Airport Link 22
Valley Local 45
Metro Loop 60
Freight 91 240
Ghost Service -3
'''


def parse_minutes(value):
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        text = value.strip()
        if text.lstrip('-').isdigit():
            return int(text)
    raise ValueError('minutes must be a whole number of minutes')


def classify(minutes):
    if minutes < 0:
        return 'invalid time'
    if minutes == 0:
        return 'on time'
    if minutes <= 5:
        return 'minor delays'
    if minutes <= 15:
        return 'moderate delays'
    if minutes <= 30:
        return 'significant delays'
    if minutes <= 59:
        return 'severe delays'
    if minutes == 60:
        return 'one hour delay'
    return 'indefinite delay'


def with_attention(phrase):
    return PREFIX + ' ' + phrase


def announce(minutes):
    phrase = classify(parse_minutes(minutes))
    if phrase == 'invalid time':
        return phrase
    return with_attention(phrase)


def parse_schedule(text):
    services = []
    for line in text.strip().splitlines():
        name, amount = line.rsplit(' ', 1)
        services.append((name.strip(), parse_minutes(amount)))
    return services


def format_report(schedule):
    lines = []
    for name, minutes in schedule:
        lines.append('{:<14} {}'.format(name, announce(minutes)))
    return '\n'.join(lines)


def urgent_services(schedule):
    return [name for name, minutes in schedule
            if classify(minutes) == 'indefinite delay']


def main():
    schedule = parse_schedule(SCHEDULE_TEXT)
    print('delay bulletin'.upper())
    print(format_report(schedule))
    urgent = urgent_services(schedule)
    if urgent:
        names = ', '.join(urgent)
        print('platform staff required for: ' + names)


if __name__ == '__main__':
    main()

