MENU = {
    1: [
        'burger',
        'fries',
        'cola',
    ],
    2: [
        'cheeseburger',
        'curly fries',
        'orange soda',
    ],
    3: [
        'double burger',
        'onion rings',
        'root beer',
    ],
    4: [
        'veggie burger',
        'side salad',
        'iced tea',
    ],
    5: [
        'chicken sandwich',
        'waffle fries',
        'lemonade',
    ],
}

FALLBACK = ['water']

PRICES = {
    'burger': 3.25,
    'fries': 1.75,
    'cola': 1.50,
    'cheeseburger': 3.75,
    'curly fries': 2.10,
    'orange soda': 1.60,
    'double burger': 5.40,
    'onion rings': 2.50,
    'root beer': 1.70,
    'veggie burger': 4.10,
    'side salad': 2.25,
    'iced tea': 1.40,
    'chicken sandwich': 4.60,
    'waffle fries': 2.20,
    'lemonade': 1.65,
    'water': 0.00,
}

ROW = '{0:<18}{1:>6.2f}'


def assemble(number):
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError('combo number must be an integer')
    return list(MENU.get(number, FALLBACK))


def combo_total(number):
    return sum(PRICES[item] for item in assemble(number))


def cheapest_combo():
    return min(MENU, key=combo_total)


def describe(items):
    if len(items) == 1:
        return items[0]
    head = ', '.join(items[:-1])
    return '{0} and {1}'.format(head, items[-1])


def format_receipt(number):
    items = assemble(number)
    if number in MENU:
        rows = ['Combo #{0}'.format(number)]
    else:
        rows = ['Combo #{0} is not on the menu'.format(number)]
    for item in items:
        rows.append(ROW.format(item.title(), PRICES[item]))
    rows.append('-' * 24)
    rows.append(ROW.format('TOTAL', combo_total(number)))
    rows.append('You get {0}.'.format(describe(items)))
    return '\n'.join(rows)


def main():
    for number in (1, 2, 3, 4, 5, 9):
        print(format_receipt(number))
        print()
    best = cheapest_combo()
    print('Best value: combo #{0} for ${1:.2f}'.format(best, combo_total(best)))


if __name__ == '__main__':
    main()

