    ("air", _AIR_SIGNS),
    ("water", _WATER_SIGNS),
):
    for _sign in _signs:
        _SIGN_ELEMENTS[_sign] = _element


def element(sign):
    if not isinstance(sign, str):
        raise TypeError("element() expects the sign to be given as a string")
    key = sign.strip().lower()
    if not key:
        raise ValueError("the sign must contain at least one character")
    return _SIGN_ELEMENTS.get(key, UNKNOWN_ELEMENT)


def elements(signs):
    return [element(sign) for sign in signs]


def group_by_element(signs):
    grouped = {}
    for sign in signs:
        grouped.setdefault(element(sign), []).append(sign.strip().lower())
    return grouped


def format_report(signs):
    lines = ["sign          element"]
    lines.append("-" * 30)
    for sign, name in zip(signs, elements(signs)):
        lines.append(f"{sign.strip().lower():<14}{name}")
    return "\n".join(lines)


def main():
    chart = [
        "Aries",
        "libra",
        " cancer ",
        "capricorn",
        "Scorpio",
        "ophiuchus",
    ]
    print(format_report(chart))
    print()
    grouped = group_by_element(chart)
    for name in sorted(grouped):
        members = ", ".join(grouped[name])
        print(f"{name}: {members}")


if __name__ == "__main__":
    main()

