WINTER = 'winter'
GREENHOUSE = 'greenhouse'
JOINER = ', '

SEASON_ORDER = (SPRING, SUMMER, AUTUMN, WINTER, GREENHOUSE)

CROP_SEASONS = {
    'peas': SPRING,
    'spinach': SPRING,
    'radishes': SPRING,
    'tomatoes': SUMMER,
    'peppers': SUMMER,
    'eggplants': SUMMER,
    'kale': AUTUMN,
    'carrots': AUTUMN,
    'turnips': AUTUMN,
    'garlic': WINTER,
    'onions': WINTER,
    'winter wheat': WINTER,
}

PLURAL_SUFFIXES = (
    's',
    'es',
)


def _resolve(crop):
    name = crop.strip().lower()
    if name in CROP_SEASONS:
        return name
    for suffix in PLURAL_SUFFIXES:
        candidate = name + suffix
        if candidate in CROP_SEASONS:
            return candidate
    return name


def plant(crop):
    return CROP_SEASONS.get(_resolve(crop), GREENHOUSE)


