WATER_PHRASE = 'tall enough for water rides'
DEFAULT_PHRASE = 'check with operator'

REQUIREMENTS = {
    'roller coaster': THRILL_PHRASE,
    'drop tower': THRILL_PHRASE,
    'ferris wheel': ANY_HEIGHT_PHRASE,
    'carousel': ANY_HEIGHT_PHRASE,
    'bumper cars': MEDIUM_PHRASE,
