    'water slide': WATER_PHRASE,
}


def normalize(ride):
    if not isinstance(ride, str):
        raise TypeError('ride must be given as a string')
    return ' '.join(ride.split()).lower()


def allow(ride):
    return REQUIREMENTS.get(normalize(ride), DEFAULT_PHRASE)


def describe(ride):
    name = normalize(ride)
    if not name:
        name = '(unnamed attraction)'
