SPRINT_EVENTS = (
    '100 meter',
    '200 meter',
    '400 meter',
)

MIDDLE_DISTANCE_EVENTS = (
    '800 meter',
    '1500 meter',
)

LONG_DISTANCE_EVENTS = (
    '5000 meter',
    '10000 meter',
)

OBSTACLE_MARKERS = (
    'hurdle',
    'steeplechase',
)

JUMP_EVENTS = (
    'high jump',
    'pole vault',
    'long jump',
    'triple jump',
)

THROW_EVENTS = (
    'shot put',
    'discus',
    'hammer',
    'javelin',
)

DESCRIPTORS = (
    'sprint',
    'dash',
    'run',
    'race',
    'throw',
)


def normalize(event):
    if not isinstance(event, str):
        raise TypeError('event name must be a string')
    words = [word for word in event.lower().split() if word not in DESCRIPTORS]
    if not words:
        raise ValueError('event name must not be blank')
    name = ' '.join(words)
    if name.endswith('s'):
        name = name[:-1]
    return name


def group(event):
    name = normalize(event)
    if name in SPRINT_EVENTS:
        return 'sprints'
    if name in MIDDLE_DISTANCE_EVENTS:
        return 'middle distance'
    if name in LONG_DISTANCE_EVENTS:
        return 'long distance'
    if any(marker in name for marker in OBSTACLE_MARKERS):
        return 'obstacle events'
    if name in JUMP_EVENTS:
        return 'jumping events'
    if name in THROW_EVENTS:
        return 'throwing events'
    return 'decathlon'


def summarize(events):
    buckets = {}
    for event in events:
        buckets.setdefault(group(event), []).append(event)
