)

DESCRIPTORS = (
    "sprint",
    "dash",
    "run",
    "race",
    "throw",
)


def normalize(event):
    if not isinstance(event, str):
        raise TypeError("event name must be a string")
    words = [word for word in event.lower().split() if word not in DESCRIPTORS]
    if not words:
        raise ValueError("event name must not be blank")
    name = " ".join(words)
    if name.endswith("s"):
