    return name


def group(event):
    name = normalize(event)
    if name in SPRINT_EVENTS:
        return "sprints"
    if name in MIDDLE_DISTANCE_EVENTS:
        return "middle distance"
    if name in LONG_DISTANCE_EVENTS:
