    if not isinstance(dessert, str):
        raise TypeError('dessert must be given as text')
    pieces = dessert.lower().split('-')
    joined = ' '.join(pieces)
    cleaned = ' '.join(joined.split())
    if not cleaned:
        raise ValueError('dessert must not be blank')
    return cleaned


