def _normalize(feature):
    if not isinstance(feature, str):
        raise TypeError('cave() expects the feature keyword as a string')
    key = feature.strip().lower()
    if not key:
        raise ValueError('the feature keyword must not be empty')
    return key


def cave(feature):
    key = _normalize(feature)
    if key == 'ceiling':
        return 'stalactites'
    if key == 'floor':
        return 'stalagmites'
    if key == 'connected':
        return 'pillars'
    if key == 'wall':
        return 'flowstones'
    if key == 'tube':
        return 'soda straws'
    if key == 'round':
        return 'cave pearls'
    if key == 'underwater':
        return 'pool fingers'
    return 'generic speleothem'


def describe(feature):
    deposit = cave(feature)
    label = _normalize(feature)
