NOISE = r'[^a-z ]+'
FORWARD = 'forward'
BACKWARD = 'backward'
OUTSIDE = 'outside'
INSIDE = 'inside'
TOE = 'toe'
HALF = 'half'


def normalize(phrase):
    cleaned = re.sub(NOISE, ' ', phrase.lower())
    return ' '.join(cleaned.split())


def parse(mechanics):
    if not isinstance(mechanics, list):
        raise TypeError('mechanics must be a list of movement phrases')
    phrases = [normalize(item) for item in mechanics if normalize(item)]
    if not phrases:
        raise ValueError('at least one movement phrase is required')
    return phrases


def describes(phrases, *keywords):
    return any(all(word in phrase for word in keywords) for phrase in phrases)


def read_edge(phrases):
    if describes(phrases, FORWARD, OUTSIDE):
        return (FORWARD, OUTSIDE)
    if describes(phrases, FORWARD, INSIDE):
        return (FORWARD, INSIDE)
    if describes(phrases, BACKWARD, OUTSIDE):
        return (BACKWARD, OUTSIDE)
    if describes(phrases, BACKWARD, INSIDE):
        return (BACKWARD, INSIDE)
    raise ValueError('no takeoff edge found in the mechanics')


def read_assist(phrases):
    if describes(phrases, 'counter', TOE):
        return 'counter'
    if describes(phrases, TOE):
        return TOE
    return None


def judge(mechanics):
    phrases = parse(mechanics)
    edge = read_edge(phrases)
    assist = read_assist(phrases)
    landings = [text for text in phrases if 'land' in text]
    if describes(landings, 'opposite', INSIDE):
        return 'Euler'
    if edge == (FORWARD, OUTSIDE):
        if describes(phrases, 'extra', HALF):
            return 'Axel'
        if describes(phrases, HALF):
            return 'Waltz'
        return 'Axel'
    if edge == (BACKWARD, OUTSIDE):
        if assist == 'counter':
            return 'Lutz'
        if assist == TOE:
            return 'Toe Loop'
        return 'Loop'
    if edge == (BACKWARD, INSIDE):
        if assist is None:
            return 'Salchow'
        return 'Flip'
    raise ValueError('the described edge matches no known jump')


def main():
    program = [
        ['forward outside edge takeoff with half rotation'],
        ['backward outside edge takeoff with counter rotational toe pick'],
        ['backward inside takeoff landing on the opposite foot inside edge'],
    ]
    for mechanics in program:
