import re
import sys

BRUSH_WORDS = {
    'brush',
    'brushes',
    'brushing',
}
STEP_WORDS = {
    'step',
    'steps',
    'stepping',
}
HOP_WORDS = {
    'hop',
    'hops',
    'hopping',
}
LEAP_WORDS = {
    'leap',
    'leaps',
    'jump',
}
FORWARD_WORDS = {
    'forward',
    'front',
}
BACK_WORDS = {
    'back',
    'backward',
}
OUT_WORDS = {
    'out',
    'outward',
}
IN_WORDS = {
    'in',
    'inward',
}
WEIGHT_WORDS = {
    'weight',
    'shift',
}
ALTERNATING_WORDS = {
    'alternating',
    'alternate',
}
AIRBORNE_WORDS = {
    'airborne',
    'air',
}
BOTH_WORDS = {
    'both',
    'together',
}
SIDEWAYS_WORDS = {
    'sideways',
    'traveling',
}
SHUFFLE_PATTERN = [
    'brush_forward',
    'brush_back',
]
FLAP_PATTERN = [
    'brush_forward',
    'step_weight',
]
WING_PATTERN = [
    'brush_out',
    'brush_in',
]
CRAMP_ROLL_PATTERN = [
    'ball',
    'ball',
    'heel',
    'heel',
]


def canonicalize(words):
    events = []
    for word in words:
        if word in BRUSH_WORDS:
            events.append('brush')
        elif word in STEP_WORDS:
            events.append('step')
        elif word in HOP_WORDS:
            events.append('hop')
        elif word in LEAP_WORDS:
            events.append('leap')
        elif word == 'ball':
            events.append('ball')
        elif word == 'heel':
            events.append('heel')
        elif not events:
            continue
        elif word in FORWARD_WORDS:
            events[-1] = events[-1] + '_forward'
        elif word in BACK_WORDS:
            events[-1] = events[-1] + '_back'
        elif word in OUT_WORDS:
            events[-1] = events[-1] + '_out'
        elif word in IN_WORDS:
            events[-1] = events[-1] + '_in'
        elif word in WEIGHT_WORDS:
            events[-1] = 'step_weight'
    return events


def collect_flags(words):
    flags = set()
    if words & ALTERNATING_WORDS:
        flags.add('alternating')
    if words & AIRBORNE_WORDS:
        flags.add('airborne')
    if words & BOTH_WORDS:
        flags.add('both')
    if words & SIDEWAYS_WORDS:
        flags.add('sideways')
    return flags


def parse(sequence):
    if not sequence.strip():
        raise ValueError('sequence must describe at least one foot strike')
    words = [word for word in re.split(r'[^a-z]+', sequence.lower()) if word]
    return canonicalize(words), collect_flags(set(words))


def contains_shuffle(events):
    for index in range(len(events) - 1):
        if events[index:index + 2] == SHUFFLE_PATTERN:
            return True
    return False


def is_buffalo(events, flags):
    if 'sideways' not in flags:
        return False
    if 'leap' not in events:
        return False
    if 'step' not in events:
