import re
import sys

_STATEMENT_SPLIT = re.compile(r'[\n;]+')
_LINK_SPLIT = re.compile(r'--+|<->|->|-|\bto\b')
_CABLE_WORDS = (
    'bus',
    'backbone',
    'cable',
)


def _parse(layout):
    if not isinstance(layout, str):
        raise TypeError('layout must be given as text')
    statements = [part.strip() for part in _STATEMENT_SPLIT.split(layout) if part.strip()]
    if not statements:
        raise ValueError('layout description is empty')
    edges = []
    for statement in statements:
        if ':' in statement:
            head, tail = statement.split(':', 1)
            hub = head.strip()
            if not hub:
                raise ValueError(f'missing central node in {statement!r}')
            for child in tail.split(','):
                leaf = child.strip()
                if leaf:
                    edges.append((hub, leaf))
            continue
        for link in statement.split(','):
            nodes = [name.strip() for name in _LINK_SPLIT.split(link) if name.strip()]
            if len(nodes) < 2:
                raise ValueError(f'cannot read the connection {link.strip()!r}')
            edges.extend(zip(nodes, nodes[1:]))
    return edges


def _graph(layout):
    adjacency = {}
    unique = set()
    for left, right in _parse(layout):
        adjacency.setdefault(left, set()).add(right)
        adjacency.setdefault(right, set()).add(left)
        unique.add(frozenset((left, right)))
    return unique, adjacency


def _connected(adjacency):
    start = next(iter(adjacency))
    seen = {start}
    queue = [start]
    while queue:
        for neighbour in adjacency[queue.pop()]:
            if neighbour not in seen:
                seen.add(neighbour)
                queue.append(neighbour)
    return len(seen) == len(adjacency)


def identify(layout):
    edges, adjacency = _graph(layout)
    order = len(adjacency)
    size = len(edges)
    degrees = {node: len(peers) for node, peers in adjacency.items()}
    if order == 2 and size == 1:
        return 'Point to Point'
    if not _connected(adjacency):
        return 'Hybrid'
    if order >= 4 and size == order * (order - 1) // 2:
        return 'Mesh'
    if all(degree == 2 for degree in degrees.values()):
        return 'Ring'
    if size > order - 1:
        return 'Hybrid'
    hubs = [node for node, degree in degrees.items() if degree == order - 1]
    if hubs:
        label = hubs[0].lower()
        if any(word in label for word in _CABLE_WORDS):
            return 'Bus'
        return 'Star'
    if sum(1 for degree in degrees.values() if degree == 1) == 2:
        return 'Daisy Chain'
    return 'Tree'


def describe(layout):
    edges, adjacency = _graph(layout)
    return f'{identify(layout)} ({len(adjacency)} nodes, {len(edges)} links)'


def main(argv):
    try:
        if len(argv) > 1:
            with open(argv[1], encoding='utf-8') as handle:
                text = handle.read()
        else:
            text = sys.stdin.read()
        print(describe(text))
    except OSError as exc:
        print(f'cannot open layout file: {exc}', file=sys.stderr)
        return 2
    except (TypeError, ValueError) as exc:
        print(f'invalid layout: {exc}', file=sys.stderr)
        return 1
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

