import sys


def remove_duplicates(items):
    # Return a new list without duplicates, keeping first occurrences.
    seen = set()
    unhashable = []
    result = []
    for item in items:
        try:
            if item in seen:
                continue
            seen.add(item)
        except TypeError:
            if item in unhashable:
                continue
            unhashable.append(item)
        result.append(item)
    return result


def parse_token(token):
    # Convert a text token into an int, a float or a stripped string.
    text = token.strip()
    if not text:
        raise ValueError('empty token is not a valid value')
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return text


def parse_values(text, separator=','):
    tokens = [part for part in text.split(separator) if part.strip()]
    if not tokens:
        raise ValueError('no values found in input')
    return [parse_token(token) for token in tokens]


def describe(value):
    if isinstance(value, bool):
        return 'bool'
    if isinstance(value, int):
        return 'int'
    if isinstance(value, float):
        return 'float'
    return 'str'


def format_report(original, unique):
    lines = []
    lines.append('input   : {0!r}'.format(original))
    lines.append('unique  : {0!r}'.format(unique))
    removed = len(original) - len(unique)
    lines.append('removed : {0} duplicate(s)'.format(removed))
    kinds = remove_duplicates([describe(value) for value in unique])
    joined = ', '.join(kinds)
    lines.append('types   : {0}'.format(joined))
    return '\n'.join(lines)


def main(argv):
    if len(argv) < 2:
        print('usage: dedup.py VALUES [separator]')
        return 1
    separator = argv[2] if len(argv) > 2 else ','
    try:
        values = parse_values(argv[1], separator)
    except ValueError as error:
        print('error: {0}'.format(error))
        return 2
    print(format_report(values, remove_duplicates(values)))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

