def find_missing_number(numbers):
    n = len(numbers) + 1  # 'n' is the expected length of the complete sequence
    expected_sum = n * (n + 1) // 2  # 'Calculate the sum of numbers from 1 to n'
    actual_sum = sum(numbers)  # 'Sum the numbers present in the input list'

    if not numbers:
        return 1  # 'Handle the edge case of an empty list'
    if not all(isinstance(x, int) for x in numbers):
        raise TypeError('All elements must be integers.') # 'Error for non-integer elements'
    if not all(1 <= x <= n for x in numbers):
        raise ValueError('Numbers must be within the range [1, N].') # 'Error for out of range numbers'

    missing = expected_sum - actual_sum # 'Compute the difference to find the missing number'
    return missing # 'Return the calculated missing number'

