def parse_time(text):
    'Convert a time string such as 09:30 into minutes past midnight.'
    parts = text.split(':')
    if len(parts) != 2:
        raise ValueError('expected a time in HH:MM form, got ' + repr(text))
    hours, minutes = parts
    if not hours.isdigit() or not minutes.isdigit():
        raise ValueError('time fields must be digits: ' + text)
    total = int(hours) * 60 + int(minutes)
    if total >= 24 * 60:
        raise ValueError('time out of range: ' + text)
    return total


def format_time(minutes):
    'Render minutes past midnight back into an HH:MM string.'
    return '{:02d}:{:02d}'.format(minutes // 60, minutes % 60)


def validate_interval(start, end):
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError('event times must be integers')
    if start >= end:
        raise ValueError('an event must end after it starts')
    return start, end


def has_conflict(schedule, new_event_start, new_event_end):
    start, end = validate_interval(new_event_start, new_event_end)
    for existing_start, existing_end in schedule:
        validate_interval(existing_start, existing_end)
        if start < existing_end and existing_start < end:
            return True
    return False


def conflicting_events(schedule, new_event_start, new_event_end):
    'List the events that overlap the proposed slot.'
    return [slot for slot in schedule
            if has_conflict([slot], new_event_start, new_event_end)]


def describe_slot(slot):
    return '-'.join([format_time(slot[0]), format_time(slot[1])])


def book(schedule, request):
    'Try to add a requested slot given as two whitespace-separated times.'
    fields = request.split()
    if len(fields) != 2:
        raise ValueError('a booking request needs a start and an end')
    start, end = (parse_time(field) for field in fields)
    clashes = conflicting_events(schedule, start, end)
    if clashes:
        joined = ', '.join(describe_slot(slot) for slot in clashes)
        return 'REJECTED {} clashes with {}'.format(
            describe_slot((start, end)), joined)
    schedule.append((start, end))
    schedule.sort()
    return 'BOOKED   ' + describe_slot((start, end))


def main():
    opening = parse_time('09:00')
    schedule = [(opening, opening + 60)]
    requests = ['10:00 11:00',
                '09:30 09:45',
                '13:15 14:00',
                '10:30 12:00']
    print('initial schedule: ' + describe_slot(schedule[0]))
    for request in requests:
        print(book(schedule, request))
    print('final schedule:')
    for slot in schedule:
        print('  ' + describe_slot(slot))
    afternoon_busy = has_conflict(schedule, 13 * 60, 14 * 60)
    print('afternoon busy: ' + str(afternoon_busy))


if __name__ == '__main__':
    main()

