def char_frequency(text):
    if not isinstance(text, str):
        raise TypeError('char_frequency expects a string')
    frequency_map = {}
    for character in text.lower():
        frequency_map[character] = frequency_map.get(character, 0) + 1
    return frequency_map


def letters_only(text):
    cleaned = ''.join(character for character in text if character.isalpha())
    return char_frequency(cleaned)


def most_common(frequency_map, limit=3):
    if limit < 1:
        raise ValueError('limit must be at least 1')
    ordered = sorted(frequency_map.items(), key=lambda pair: (-pair[1], pair[0]))
    return ordered[:limit]


def describe_character(character):
    if character == ' ':
        return '<space>'
    if character == '\t':
        return '<tab>'
    if character == '\n':
        return '<newline>'
    return character


def format_row(character, count, total):
    share = count / total * 100 if total else 0.0
    label = describe_character(character).ljust(9)
    return '{0} {1:>5} {2:>7.1f}%'.format(label, count, share)


def build_report(text, limit=3):
    frequency_map = char_frequency(text)
    total = sum(frequency_map.values())
    if total == 0:
        return 'no characters to report'
    lines = ['character count   share']
    for character, count in most_common(frequency_map, limit):
        lines.append(format_row(character, count, total))
    lines.append('distinct characters: {0}'.format(len(frequency_map)))
    return '\n'.join(lines)


def main():
    samples = []
    samples.append('hello')
    samples.append('Python')
    samples.append('Mississippi River')
    samples.append('')
    for sample in samples:
        title = sample if sample else '<empty string>'
        print('=== {0} ==='.format(title))
        print(char_frequency(sample))
        print(build_report(sample))
        alphabetic = letters_only(sample)
        if alphabetic != char_frequency(sample):
            print('letters only: {0}'.format(alphabetic))
        print('')

    try:
        char_frequency(42)
    except TypeError as error:
        print('rejected bad input: {0}'.format(error))


if __name__ == '__main__':
    main()

