from datetime import datetime

def days_remaining(start_date_str, end_date_str):
    'Calculates the number of days remaining between two dates.'
    date_format = '%Y-%m-%d'
    try:
        start_date = datetime.strptime(start_date_str, date_format)
        end_date = datetime.strptime(end_date_str, date_format)
    except ValueError:
        raise ValueError('Invalid date format. Dates must be in YYYY-MM-DD format.')

    if start_date > end_date:
        raise ValueError('Start date cannot be after end date.')

    time_difference = end_date - start_date
    'The difference is a timedelta object.'
    return time_difference.days

