def flatten_dict(nested_dict, separator):
    if not isinstance(nested_dict, dict):
        raise TypeError('nested_dict must be a dict')
    if not isinstance(separator, str):
        raise TypeError('separator must be a str')
    if separator == '':
        raise ValueError('separator must not be empty')
    flattened_dict = {}
    for key, value in nested_dict.items():
        if isinstance(value, dict):
            for inner_key, inner_value in value.items():
                flattened_dict[str(key) + separator + str(inner_key)] = inner_value
        else:
            flattened_dict[str(key)] = value
    return flattened_dict


def unflatten_dict(flat_dict, separator):
    nested = {}
    for key, value in flat_dict.items():
        head, found, tail = key.partition(separator)
        if found:
            nested.setdefault(head, {})[tail] = value
        else:
            nested[key] = value
    return nested


def describe_value(value):
    if isinstance(value, bool):
        return 'bool'
    if isinstance(value, float):
        return 'float'
    if isinstance(value, int):
        return 'int'
    return type(value).__name__


def format_report(flat_dict):
    if not flat_dict:
        return '(empty)'
    lines = []
    for key in sorted(flat_dict):
        value = flat_dict[key]
        lines.append('{0} = {1} ({2})'.format(key, value, describe_value(value)))
    return '\n'.join(lines)


def main():
    letters = {
        'c': 2,
        'd': 3,
    }
    basic = {
        'a': 1,
        'b': letters,
    }
    point = {
        'y': 10,
    }
    coords = {
        'x': point,
    }
    scores = {
        'math': 99.5,
        'art': 80,
    }
    profile = {
        'scores': scores,
        'active': True,
    }
    samples = [
        (basic, '_'),
        (coords, '.'),
        (profile, '/'),
    ]
    for nested, separator in samples:
        flat = flatten_dict(nested, separator)
        print('separator: ' + repr(separator))
        print(format_report(flat))
        if unflatten_dict(flat, separator) == nested:
            print('round-trip ok')
        else:
            print('round-trip mismatch')
        print('-' * 30)


if __name__ == '__main__':
    main()

