def validate_interval(start, end, label):
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError(label + ' must be given as integer hours')
    if not 0 <= start <= 24 or not 0 <= end <= 24:
        raise ValueError(label + ' must lie between 0 and 24 hours')
    if start >= end:
        raise ValueError(label + ' must start before it ends')
    return start, end


def has_overlap(task1_start, task1_end, task2_start, task2_end):
    validate_interval(task1_start, task1_end, 'task 1')
    validate_interval(task2_start, task2_end, 'task 2')
    return task1_start < task2_end and task2_start < task1_end


def overlap_hours(task1_start, task1_end, task2_start, task2_end):
    if not has_overlap(task1_start, task1_end, task2_start, task2_end):
        return 0
    return min(task1_end, task2_end) - max(task1_start, task2_start)


def parse_interval(text):
    parts = text.split('-')
    if len(parts) != 2:
        raise ValueError('an interval looks like 9-12')
    return int(parts[0].strip()), int(parts[1].strip())


def parse_pair(text):
    halves = text.split(',')
    if len(halves) != 2:
        raise ValueError('two intervals must be separated by a comma')
    return parse_interval(halves[0]), parse_interval(halves[1])


def format_hour(hour):
    if hour < 12:
        suffix = 'am'
    else:
        suffix = 'pm'
    display = hour % 12
    if display == 0:
        display = 12
    return '{0}{1}'.format(display, suffix)


def format_interval(start, end):
    return format_hour(start) + '\u2013' + format_hour(end)


def describe(task1_start, task1_end, task2_start, task2_end):
    first = format_interval(task1_start, task1_end)
    second = format_interval(task2_start, task2_end)
    shared = overlap_hours(task1_start, task1_end, task2_start, task2_end)
    if shared == 0:
        verdict = 'no conflict'
    else:
        verdict = 'conflict of {0}h'.format(shared)
    return '{0} vs {1}: {2}'.format(first, second, verdict)


