ROW_FORMAT = '{:>4}  {:>14}  {:>14}'


def calculate_simple_interest(principal, rate, time):
    if principal < 0:
        raise ValueError('principal must not be negative')
    if rate < 0:
        raise ValueError('rate must not be negative')
    if time < 0:
        raise ValueError('time must not be negative')
    return principal * rate * time / 100.0


def parse_loan(text):
    parts = [item.strip() for item in text.split(',')]
    if len(parts) != 3:
        raise ValueError('expected three comma-separated values')
    principal = float(parts[0])
    rate = float(parts[1].rstrip('%'))
    time = int(parts[2])
    return principal, rate, time


def build_schedule(principal, rate, time):
    schedule = []
    for year in range(1, time + 1):
        interest = calculate_simple_interest(principal, rate, year)
        schedule.append((year, interest, principal + interest))
    return schedule


def format_money(amount):
    return '{:,.2f}'.format(amount)


def format_row(entry):
    year, interest, total = entry
    return ROW_FORMAT.format(year, format_money(interest), format_money(total))


def render_report(principal, rate, time):
    header = 'Simple interest on {} at {}% for {} year(s)'.format(
        format_money(principal), rate, time)
    columns = ROW_FORMAT.format(
        'Yr',
        'Interest',
        'Balance',
    )
    lines = [header, columns]
    for entry in build_schedule(principal, rate, time):
        lines.append(format_row(entry))
    if time > 0:
        total = calculate_simple_interest(principal, rate, time)
        lines.append('Total interest: ' + format_money(total))
    else:
        lines.append('No interest accrues over a zero-year term.')
    return '\n'.join(lines)


def main():
    loans = [
        '1000, 5%, 2',
        '500, 2.5%, 10',
        '2500, 7.25%, 0',
    ]
    for loan in loans:
        principal, rate, time = parse_loan(loan)
        print(render_report(principal, rate, time))
        print('-' * 36)
    bad = '1000, -3, 5'
    principal, rate, time = parse_loan(bad)
    try:
        calculate_simple_interest(principal, rate, time)
    except ValueError as error:
        print('Rejected {!r}: {}'.format(bad, error))


if __name__ == '__main__':
    main()

