def calculate_compound_interest(principal, rate, compounding_frequency, time_years):
    if principal < 0:
        raise ValueError('principal must be non-negative')
    if rate < 0:
        raise ValueError('rate must be non-negative')
    if compounding_frequency < 1:
        raise ValueError('compounding_frequency must be at least 1')
    if time_years < 0:
        raise ValueError('time_years must be non-negative')
    periods = compounding_frequency * time_years
    return principal * (1 + rate / compounding_frequency) ** periods


def interest_earned(principal, rate, compounding_frequency, time_years):
    total = calculate_compound_interest(principal, rate, compounding_frequency, time_years)
    return total - principal


def frequency_name(compounding_frequency):
    names = {
        1: 'annually',
        2: 'semi-annually',
        4: 'quarterly',
        12: 'monthly',
        365: 'daily',
    }
    return names.get(compounding_frequency, '{0} times per year'.format(compounding_frequency))


def format_money(amount, symbol='$'):
    return '{0}{1:,.2f}'.format(symbol, amount)


def growth_schedule(principal, rate, compounding_frequency, time_years):
    rows = []
    for year in range(1, time_years + 1):
        total = calculate_compound_interest(principal, rate, compounding_frequency, year)
        rows.append((year, total, total - principal))
    return rows


def describe_investment(principal, rate, compounding_frequency, time_years):
    total = calculate_compound_interest(principal, rate, compounding_frequency, time_years)
    earned = interest_earned(principal, rate, compounding_frequency, time_years)
    lines = [
        'Principal: ' + format_money(principal),
        'Rate: {0:.2f}% compounded {1}'.format(rate * 100, frequency_name(compounding_frequency)),
        'Term: {0} year(s)'.format(time_years),
        'Final amount: ' + format_money(total),
        'Interest earned: ' + format_money(earned),
    ]
    return '\n'.join(lines)


def main():
    scenarios = [
        (1000.0, 0.05, 1, 1),
        (1000.0, 0.05, 4, 1),
        (2500.0, 0.043, 12, 5),
    ]
    for principal, rate, frequency, years in scenarios:
        print(describe_investment(principal, rate, frequency, years))
        print('-' * 40)
    headings = [
        'Year',
        'Balance',
        'Interest',
    ]
    row_format = '{0:>6} {1:>14} {2:>14}'
    print('Yearly growth for the last scenario:')
    print(row_format.format(*headings))
    for year, total, earned in growth_schedule(*scenarios[-1]):
        print(row_format.format(year, format_money(total), format_money(earned)))


if __name__ == '__main__':
    main()

