def longest_common_prefix(strings: list[str]) -> str:
    if not strings:
        return ""

    shortest_string = min(strings, key=len)
    common_prefix = ""

    for i, char in enumerate(shortest_string):
        is_common = True
        for s in strings:
            if s[i] != char:
                is_common = False
                break
        if is_common:
            common_prefix += char
        else:
            break

    return common_prefix

if __name__ == "__main__":
    test_cases = [
        (["flower", "flow", "flight"], "fl"),
        (["dog", "racecar", "car"], ""),
        (["apple", "apricot", "april"], "ap"),
        (["a"], "a"),
        ([], ""),
        (["abc", "ab"], "ab"),
        (["same", "same", "same"], "same"),
        (["diff", "different", "difficult"], "diff"),
        (["", "a", "b"], ""),
        (["hello", "world"], ""),
    ]

    for input_strings, expected_output in test_cases:
        actual_output = longest_common_prefix(input_strings)
