def parse_time(text):
    'Convert a HH:MM string into minutes from midnight.'
    parts = text.split(':')
    if len(parts) != 2:
        raise ValueError('time must look like HH:MM, got ' + repr(text))
    hours, minutes = parts
    if not hours.isdigit() or not minutes.isdigit():
        raise ValueError('time fields must be digits, got ' + repr(text))
    hours, minutes = int(hours), int(minutes)
    if hours > 23 or minutes > 59:
        raise ValueError('time out of range: ' + text)
    return hours * 60 + minutes


def format_time(minutes):
    'Render minutes from midnight as HH:MM.'
    return '{:02d}:{:02d}'.format(minutes // 60, minutes % 60)


def parse_event(text):
    'Turn a range such as 09:00-10:30 into a start/end tuple.'
    pieces = text.split('-')
    if len(pieces) != 2:
        raise ValueError('event must look like HH:MM-HH:MM, got ' + repr(text))
    start = parse_time(pieces[0].strip())
    end = parse_time(pieces[1].strip())
    if end < start:
        raise ValueError('event ends before it starts: ' + text)
    return (start, end)


def validate_event(event):
    'Check that an event is a pair of ordered integer times.'
    if len(event) != 2:
        raise ValueError('an event needs exactly two times')
    start, end = event
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError('event times must be integers')
    if end < start:
        raise ValueError('event ends before it starts')
    return (start, end)


def check_event_overlap(event1, event2):
    'Return True when the two events share at least one minute.'
    start1, end1 = validate_event(event1)
    start2, end2 = validate_event(event2)
    return start1 < end2 and start2 < end1


def describe_event(event):
    'Describe an event as a readable time range.'
    start, end = validate_event(event)
    return format_time(start) + '-' + format_time(end)


def find_conflicts(schedule):
    'List every pair of overlapping events in a schedule.'
    conflicts = []
    for i, first in enumerate(schedule):
        for second in schedule[i + 1:]:
            if check_event_overlap(first, second):
                conflicts.append((first, second))
    return conflicts


def report(schedule):
    'Build a human readable conflict report for a schedule.'
    lines = ['Schedule with {} events'.format(len(schedule))]
    for event in schedule:
        lines.append('  ' + describe_event(event))
    conflicts = find_conflicts(schedule)
    if not conflicts:
        lines.append('No conflicts found')
    for first, second in conflicts:
        pair = describe_event(first) + ' vs ' + describe_event(second)
        lines.append('CONFLICT: ' + pair)
    return '\n'.join(lines)


def main():
    raw = [
        '09:00-10:30',
        '10:00-11:00',
        '11:15-12:00',
        '13:00-14:00',
    ]
    schedule = [parse_event(entry) for entry in raw]
    print(report(schedule))


if __name__ == '__main__':
    main()

