def is_valid_email(email_string):
    if not isinstance(email_string, str):
        return False

    if '@' not in email_string:
        return False

    parts = email_string.split('@')
    if len(parts) != 2:
        return False

    local_part, domain_part = parts[0], parts[1]

    if not local_part or not domain_part:
        return False

    if '.' not in domain_part:
        return False

    if domain_part.startswith('.'):
        return False

    if domain_part.endswith('.'):
        return False

    if ' ' in email_string:
        return False

    dot_index = domain_part.find('.')
    if dot_index == -1 or dot_index == 0 or dot_index == len(domain_part) - 1:
        return False

    # A final check for more complex scenarios, though the prompt implies basic validation.
    # For instance, a domain like 'example.com' is good, 'example.' or '.com' is not.
    if domain_part.count('.') == 0:
        return False

    return True

