    "Render a set of keys as a stable, human readable string."
    if not keys:
        return "(none)"
    return ", ".join(sorted(repr(key) for key in keys))


def parse_config(text):
    "Parse newline separated key=value entries into a dictionary."
    config = {}
    for line in text.splitlines():
        entry = line.strip()
        if not entry:
            continue
        if "=" not in entry:
            raise ValueError("expected key=value but got " + repr(entry))
        key, value = entry.split("=", 1)
        config[key.strip()] = value.strip()
    return config


def merge_preferring_second(dict1, dict2):
    "Merge both mappings, letting dict2 win wherever the keys collide."
    merged = dict(dict1)
    for key in dict2:
        merged[key] = dict2[key]
    return merged


def compare_report(dict1, dict2):
    "Build a multi-line summary of how the two dictionaries relate."
    lines = ["shared keys: " + format_key_set(common_keys(dict1, dict2))]
    lines.append("only in first: " + format_key_set(only_in_first(dict1, dict2)))
    lines.append("only in second: " + format_key_set(only_in_first(dict2, dict1)))
    lines.append("value conflicts: " + format_key_set(conflicting_keys(dict1, dict2)))
    merged = merge_preferring_second(dict1, dict2)
    lines.append("merged size: {0}".format(len(merged)))
    return "\n".join(lines)


def main():
    defaults = parse_config("\n".join([
        "host=localhost",
        "port=8080",
        "retries=3",
    ]))
    overrides = parse_config("\n".join([
        "port=9090",
        "debug=false",
    ]))
    print("defaults:  {0}".format(defaults))
    print("overrides: {0}".format(overrides))
    print(compare_report(defaults, overrides))
    print("common_keys -> {0}".format(common_keys(defaults, overrides)))
    print("effective config: {0}".format(merge_preferring_second(defaults, overrides)))
    left = parse_config("x=1")
    right = parse_config("y=2")
    print(compare_report(left, right))
    print("common_keys -> {0}".format(common_keys(left, right)))


if __name__ == "__main__":
    main()

