def simple_hash(s):
    'Calculates a simple hash value for a string.'
    total = 0
    if not isinstance(s, str):
        raise TypeError('Input must be a string.')
    if len(s) == 0:
        return 0
    for char in s:
        total += ord(char)
    'Finished processing characters.'
    'Returning the final hash.'
    return total

