def censor_text(text, bad_words):
    'Censors specific words in a text.'
    censored_text = []
    words = text.split(' ')
    for word_obj in words:
        stripped_word = word_obj.lower().strip('.,!?;:')
        original_word = word_obj
        if stripped_word in [bw.lower() for bw in bad_words]:
            'This is a bad word.'
            start_punc = ''
            end_punc = ''
            'Let\'s find punctuation.'
            for char in original_word:
                if char in '.,!?;:':
                    if not start_punc:
                        start_punc = char
                    else:
                        end_punc = char
            if original_word.startswith(start_punc) and start_punc:
                original_word = original_word[len(start_punc):]
            if original_word.endswith(end_punc) and end_punc:
                original_word = original_word[:-len(end_punc)]

            censored_word = '*' * len(original_word)
            censored_text.append(start_punc + censored_word + end_punc)
        else:
            'This word is fine.'
            censored_text.append(original_word)
    'Joining the parts now.'
    return ' '.join(censored_text)

