import re

PHONE_PATTERN = re.compile(r'^\d{3}([- ]?)\d{3}\1\d{4}$')
SEPARATORS = '- '


def is_valid_us_phone_number(number):
    'Return True when number is 10 digits split by consistent hyphens or spaces.'
    if not isinstance(number, str):
        return False
    return PHONE_PATTERN.match(number) is not None


def strip_separators(number):
    'Remove hyphens and spaces from a candidate string.'
    return ''.join(ch for ch in number if ch not in SEPARATORS)


def normalize(number):
    'Strip separators so a valid number becomes a bare 10-digit string.'
    if not is_valid_us_phone_number(number):
        raise ValueError('not a valid US phone number: ' + repr(number))
    return strip_separators(number)


def format_number(number, separator='-'):
    'Render a valid number as three groups joined by separator.'
    digits = normalize(number)
    groups = [digits[0:3], digits[3:6], digits[6:10]]
    return separator.join(groups)


def describe(number):
    'Build a one-line report about a candidate phone number string.'
    if is_valid_us_phone_number(number):
        return 'valid -> ' + format_number(number)
    if not isinstance(number, str):
        return 'invalid: expected a string'
    stripped = strip_separators(number)
    if not stripped.isdigit():
        return 'invalid: contains characters other than digits, spaces or hyphens'
    if len(stripped) != 10:
        return 'invalid: found {0} digits, need 10'.format(len(stripped))
    return 'invalid: separators are inconsistent or misplaced'


def area_code(number):
    'Return the three-digit area code of a valid number.'
    return normalize(number)[:3]


def group_by_area_code(numbers):
    'Map each area code to the formatted numbers belonging to it.'
    grouped = {}
    for candidate in numbers:
        if is_valid_us_phone_number(candidate):
            grouped.setdefault(area_code(candidate), []).append(format_number(candidate))
    return grouped


def main():
    samples = [
        '123-456-7890',
        '123 456 7890',
        '1234567890',
        '(123) 456-7890',
        '123-456 7890',
        '555 010 1234',
        '12-3456-7890',
        '123-456-789',
        'abc-def-ghij',
        None,
    ]
    for sample in samples:
        print('{0!r:>16}  {1}'.format(sample, describe(sample)))

    print('numbers grouped by area code:')
    for code, numbers in sorted(group_by_area_code(samples).items()):
        joined = ', '.join(numbers)
        print('  {0}: {1}'.format(code, joined))

    dotted = [format_number(s, '.') for s in samples if is_valid_us_phone_number(s)]
    joined_dots = ', '.join(dotted)
    print('dot notation: ' + joined_dots)


if __name__ == '__main__':
    main()

