'''Utilities for turning full names into initials and related fields.'''

PERIOD = '.'
SPACE = ' '
EMPTY = ''
WORD_BREAKS = '-,'


def split_name_parts(full_name):
    'Split a full name into word tokens, ignoring extra spaces.'
    if not isinstance(full_name, str):
        raise TypeError('full name must be a string')
    cleaned = full_name
    for char in WORD_BREAKS:
        cleaned = cleaned.replace(char, SPACE)
    return [part for part in cleaned.split() if part.strip(PERIOD)]


def generate_initials(full_name):
    'Return uppercase initials separated by periods.'
    parts = split_name_parts(full_name)
    initials = [part.strip(PERIOD)[0].upper() + PERIOD for part in parts]
    return EMPTY.join(initials)


def normalize_name(full_name):
    'Collapse whitespace and capitalize each part of the name.'
    parts = split_name_parts(full_name)
    words = [part.strip(PERIOD).capitalize() for part in parts]
    return SPACE.join(words)


def build_login(full_name, domain='example.org'):
    'Build an email-style login from the leading initials and the surname.'
    parts = split_name_parts(full_name)
    if not parts:
        return EMPTY
    surname = parts[-1].strip(PERIOD).lower()
    letters = [part.strip(PERIOD)[0].lower() for part in parts[:-1]]
    prefix = EMPTY.join(letters)
    local = prefix + PERIOD + surname if prefix else surname
    return local + '@' + domain


def describe(full_name):
    'Return a one-line report for a single name.'
    initials = generate_initials(full_name)
    if not initials:
        return '<empty name>'
    fields = [normalize_name(full_name), initials, build_login(full_name)]
    return ' | '.join(fields)


def roster_report(names):
    'Return a numbered report for every name, sorted by surname.'
    def sort_key(name):
        parts = split_name_parts(name)
        return parts[-1].lower() if parts else EMPTY

    lines = []
    for index, name in enumerate(sorted(names, key=sort_key), start=1):
        lines.append('{0:>2}. {1}'.format(index, describe(name)))
    return '\n'.join(lines)


def main():
    samples = [
        'John Doe',
        '   Alice   Wonderland  ',
        'ada lovelace byron',
        'Jean-Luc Picard',
        'Van Gogh, Vincent',
        '   ',
    ]
    print(roster_report(samples))


if __name__ == '__main__':
    main()

